-- Biblioteka e madhe e përrallave, pjesa 1 nga 5 (22 përralla).
-- Përralla më të gjata (8–15 minuta lexim): popullore shqiptare, klasike të rrëfyera (Grim, Andersen, Ezopi, Peroi,
-- Kipling, Kolodi, Kerolli, Baumi e të tjera, të gjitha të lira nga e drejta e autorit) dhe përralla origjinale të Bebix-it.
-- Secila ka ilustrimin e vet (cover_svg, i kontrolluar me pastruesin e app-it) dhe dalin në app pa përditësim.
-- I sigurt për t'u ekzekutuar dy herë: përrallat që ekzistojnë (sipas slug) nuk preken. Nuk fshin asgjë.
-- Kërkon migrimet 20261024090000_stories.sql dhe 20261025090000_story_drafts.sql (kolona cover_svg, source).

insert into public.stories (slug, language, title, summary, paragraphs, categories, age_min_months, age_max_months, reading_minutes, cover_key, cover_svg, status, featured, sort_order, source)
values
(
  $s$kesulekuqja$s$, 'sq', $s$Kësulëkuqja$s$,
  $s$Përralla e njohur e vajzës me kësulë të kuqe, e treguar butë: ujku i dinak, gjyshja e zgjuar dhe një mësim për rrugën që s'duhet lënë.$s$,
  array[
    $s$Na ishte një herë një vajzë e vogël, që e donin të gjithë. Por më shumë se të gjithë e donte gjyshja e saj, që i kishte qepur me duart e veta një kësulë prej kadifeje të kuqe. Vajzës i pëlqente aq shumë, sa e mbante gjithë kohën, dhe kështu të gjithë filluan ta thërrisnin Kësulëkuqja.$s$,
    $s$Një mëngjes, nëna i tha: «Gjyshja është pak e sëmurë. Merr këtë shportë me kulaç të ngrohtë dhe me një shishe mjaltë, dhe çoja. Por dëgjo me kujdes: ec drejt në shteg, mos u largo prej tij, dhe mos fol me të panjohur.» «Mos u shqetëso, mami», tha Kësulëkuqja, e puthi dhe u nis.$s$,
    $s$Shtëpia e gjyshes ishte në anën tjetër të pyllit, pas tre lisave të mëdhenj. Pylli ishte i bukur atë mëngjes, me diell që kalonte mes degëve dhe me zogj që këndonin. Kësulëkuqja ecte me hapa të vegjël e këndonte, me shportën në krah.$s$,
    $s$Papritur, nga pas një peme doli një ujk. Ishte i madh e gri, me veshë të mprehtë dhe me një buzëqeshje të gjatë. Kësulëkuqja nuk e dinte sa i dinak ishte ujku, ndaj nuk pati frikë. «Mirëmëngjes, vogëlushe», tha ujku me zë të ëmbël. «Ku po shkon kaq herët?» «Te gjyshja», tha ajo. «Është e sëmurë dhe po i çoj kulaç.» «Dhe ku banon gjyshja?» «Pas tre lisave të mëdhenj, në shtëpinë me grilat e gjelbra.»$s$,
    $s$Ujku mendoi me vete: «Sot do të ha një drekë të shijshme.» Por tha me zë të butë: «Pse nuk i mbledh gjyshes edhe një buqetë me lule? Shiko sa lule të bukura ka në lëndinë. Do të gëzohet shumë.» Kësulëkuqja pa lulet që lëkundeshin në diell dhe harroi fjalët e nënës. Doli nga shtegu dhe filloi të mblidhte lule, njërën pas tjetrës, gjithnjë e më thellë në pyll.$s$,
    $s$Ndërkohë, ujku vrapoi me të shpejtë drejt shtëpisë së gjyshes. Por gjyshja, edhe pse e sëmurë, ishte e zgjuar. Ishte ulur në krevat duke thurur, dhe nga dritarja e pa ujkun që vinte me vrap. «Ah, ti dinak», tha me vete. U ngrit ngadalë, u fut në dollapin e madh të rrobave dhe e mbylli derën nga brenda.$s$,
    $s$Ujku trokiti. «Kush është?» pyeti gjyshja nga dollapi, me zë të ulët, por ujku s'e dëgjoi. Hapi derën, hyri dhe pa krevatin bosh. «Ku është plaka?» mërmëriti. Pastaj pa kësulën e natës së gjyshes mbi jastëk dhe syzet e saj mbi tryezë. Pati një ide. I vuri syzet, kësulën, u fut nën jorgan dhe priti Kësulëkuqen.$s$,
    $s$Kur Kësulëkuqja arriti, me shportën dhe me një buqetë të madhe me lule, u habit që dera ishte e hapur. Hyri dhe u afrua te krevati. Gjyshja dukej shumë e çuditshme. «Gjyshe», tha ajo, «çfarë veshësh të mëdhenj që ke!» «Që të të dëgjoj më mirë», tha ujku me zë të hollë.$s$,
    $s$«Gjyshe, çfarë sysh të mëdhenj që ke!» «Që të të shoh më mirë.» «Gjyshe, çfarë duarsh të mëdha që ke!» «Që të të përqafoj më mirë.» «Gjyshe... çfarë dhëmbësh të mëdhenj që ke!» «Që të të ha më mirë!» thirri ujku dhe hodhi jorganin.$s$,
    $s$Por në atë çast, dera e dollapit u hap me zhurmë dhe gjyshja doli me fshesën në dorë. «Ik që këtej, ujk i pafytyrë!» bërtiti. Kësulëkuqja bërtiti edhe ajo, aq fort sa zogjtë fluturuan nga pemët. Dhe druvari, që po priste dru pranë shtëpisë, dëgjoi britmat dhe erdhi me vrap me sëpatën në dorë.$s$,
    $s$Kur ujku pa gjyshen me fshesë, vajzën që bërtiste dhe druvarin te dera, u tremb aq shumë sa kërceu nga dritarja, me kësulën e natës ende në kokë, dhe iku me vrap në thellësi të pyllit. Thonë se s'u pa më kurrë në ato anë. Ndoshta mbante ende kësulën e gjyshes, dhe i vinte turp prej kafshëve të tjera.$s$,
    $s$Gjyshja, Kësulëkuqja dhe druvari u ulën rreth tryezës dhe hëngrën kulaçin e ngrohtë me mjaltë. Gjyshja u ndje menjëherë më mirë. Lulet që kishte mbledhur Kësulëkuqja i vunë në një vazo mbi dritare, dhe dhoma u mbush me ngjyra.$s$,
    $s$Në mbrëmje, kur u kthye në shtëpi, Kësulëkuqja i tregoi nënës gjithçka. Pastaj i tha me zë të ulët: «Mami, sot mësova diçka. Rruga që të tregojnë ata që të duan është rruga e sigurt. Dhe kur një i panjohur të flet shumë ëmbël, duhet të kesh kujdes.» Nëna e përqafoi fort. «Dhe gjithmonë, kur ke frikë, bërtit fort dhe kërko ndihmë», i tha.$s$,
    $s$Atë natë, Kësulëkuqja fjeti e qetë, me kësulën e kuqe të varur pranë krevatit. Dhe në ëndërr pa pyllin me lule, ku ecte drejt në shteg, duke kënduar, ndërsa një ujk me kësulë nate i shikonte nga larg, i turpëruar.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 36, 96, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkesulekuqja" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkesulekuqja)"/><circle cx="11.7" cy="72.1" r="18.6" fill="#8FB5A0" opacity="0.85"/><circle cx="23.3" cy="72.7" r="18.2" fill="#8FB5A0" opacity="0.85"/><path d="M33.9 51.7L43.9 100H23.9Z" fill="#5F8C76" opacity="0.85"/><circle cx="46.1" cy="73.5" r="17.6" fill="#8FB5A0" opacity="0.85"/><path d="M115.6 53.6L125.6 100H105.6Z" fill="#5F8C76" opacity="0.85"/><path d="M127.2 50.7L137.2 100H117.2Z" fill="#8FB5A0" opacity="0.85"/><path d="M143.2 39.6L153.2 100H133.2Z" fill="#5F8C76" opacity="0.85"/><path d="M0 99.6Q40 91.5 80 97.5T160 99.1V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M20 58L26 28H38L44 58Z" fill="#D9644A"/><circle cx="32" cy="22" r="8" fill="#F3D9C4"/><path d="M22 24Q22 10 32 10Q42 10 42 24L46 34Q32 26 18 34Z" fill="#D9644A"/><circle cx="29" cy="23" r="1" fill="#8A5A44"/><circle cx="35" cy="23" r="1" fill="#8A5A44"/><path d="M28 58L28 62M36 58L36 62" fill="none" stroke="#2C463B" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><path d="M44 42h10l-2 10h-6z" fill="#2C463B"/><path d="M45 42Q49 36 53 42" fill="none" stroke="#2C463B" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', true, 200, 'editor'
