(
  $s$treni-i-gjumit$s$, 'sq', $s$Treni i gjumit$s$,
  $s$Çdo mbrëmje, në orën e gjumit, një tren i vogël blu ndalon te shtrati i Arbit. Ndalesat e tij janë banja, pizhamat, libri, dhe në fund, stacioni i ëndrrave.$s$,
  array[
    $s$Çdo mbrëmje, kur hëna ngjitet mbi çati dhe dritaret e qytetit fillojnë të ndizen, një tren i vogël blu niset nga stacioni i yjeve. Ka një lokomotivë me oxhak të verdhë, tre vagonë të vegjël dhe një fener të kuq në fund. Dhe kur bën tut-tut, vetëm fëmijët e dëgjojnë.$s$,
    $s$Atë mbrëmje, treni ndaloi para dhomës së Arbit. «Tut-tut!» thirri treni. «Pasagjeri Arb, ju lutem, hipni! Treni i gjumit po niset!» Arbi ishte ende duke luajtur me kubet e tij në qilim. «Edhe pak», tha. «Treni pret», tha makinisti, një ari i vogël me kapelë blu e me mustaqe të bardha. «Por vetëm pak.»$s$,
    $s$Arbi i mblodhi kubet në kuti, një nga një, dhe hipi në vagonin e parë. Ishte i butë, me ulëse prej kadifeje e me dritare të rrumbullakëta. Treni u nis ngadalë: çaf-çuf, çaf-çuf. «Ndalesa e parë», tha ariu, «stacioni i Banjës!»$s$,
    $s$Treni ndaloi te banja. Aty, një rosë e verdhë plastike e priste në buzë të vaskës. «Mirë se erdhe!» tha rosa. «Ujë i ngrohtë, shkumë e butë, dhe pak lojë.» Arbi u la, lozi pak me rosën, bëri një mjekër me shkumë dhe qeshi. Pastaj mamaja e mbështolli me një peshqir të madh e të ngrohtë, si të ishte një kifle e sapopjekur.$s$,
    $s$«Tut-tut!» thirri treni. «Të gjithë në tren! Ndalesa e dytë: stacioni i Pizhamave!» Treni çaf-çufoi deri te dollapi i rrobave, ku pizhamat e Arbit, ato me yje të vegjël, e prisnin të palosura. «Na vish, na vish», thanë pizhamat, «se jemi të buta e të ngrohta.» Arbi i veshi: një këmbë, dy këmbë, një krah, dy krahë, dhe koka del nga lart. Tani ishte gati.$s$,
    $s$«Ndalesa e tretë», tha ariu makinist, «stacioni i Dhëmbëve!» Furça e dhëmbëve e priste në gotën e saj, me një pikë pastë si një re e vogël. «Lart e poshtë, majtas e djathtas, rreth e qark», këndoi furça, dhe Arbi i lau dhëmbët mirë, deri te dhëmbët e fundit, ku fshihen thërrimet e darkës. Pastaj pështyu shkumën dhe buzëqeshi para pasqyrës, me dhëmbët që shkëlqenin.$s$,
    $s$«Tut-tut! Ndalesa e katërt: stacioni i Librit!» Treni ndaloi te rafti i librave. Arbi zgjodhi një libër me figura, për një peshk të vogël që kërkonte shtëpinë e tij. Babai u ul pranë shtratit dhe e lexoi me zë të ulët, duke i bërë zërat e peshkut, të gaforres e të oktapodit. Arbi e dëgjoi me kokën mbi jastëk dhe me sytë që i rëndoheshin pak.$s$,
    $s$«Ndalesa e pestë», pëshpëriti ariu makinist, sepse tani duhej folur më ngadalë, «stacioni i Përqafimeve.» Mamaja dhe babai e përqafuan fort Arbin, njëri nga njëra anë, tjetri nga ana tjetër, si një sanduiç me dashuri. «Natën e mirë, zemra jonë», i thanë. «Të duam deri në hënë dhe mbrapsht.» Dhe ia fikën dritën e madhe, duke lënë ndezur vetëm dritën e vogël pranë shtratit.$s$,
    $s$Tani treni po ecte shumë ngadalë: çaf... çuf... çaf... çuf. Jashtë dritares, Arbi shihte qytetin që po flinte. Kalonin pranë dritareve të errëta, pranë pemëve që lëkundeshin butë, pranë një mace që flinte mbi një mur. Kalonin mbi një urë, mbi një lumë ku hëna pasqyrohej si një monedhë argjendi.$s$,
    $s$«Ku po shkojmë tani?» pyeti Arbi, me zë të përgjumur. «Te stacioni i fundit», tha ariu me butësi. «Stacioni i Ëndrrave. Por që të arrish atje, duhet të bësh një gjë.» «Çfarë?» «Duhet të mbyllësh sytë. Vetëm me sy të mbyllur mund ta shohësh stacionin e ëndrrave.»$s$,
    $s$Arbi mbylli sytë. Dhe ndjeu trenin që lëkundej ngadalë, si një djep. Çaf... çuf... Ndjeu batanijen e ngrohtë mbi supe. Ndjeu ariun e tij të vogël pranë faqes. Dëgjoi, larg, një qen që lehte një herë dhe pastaj heshti. Dëgjoi frymëmarrjen e tij, të ngadaltë e të qetë: brenda... jashtë... brenda... jashtë.$s$,
    $s$«Tut», bëri treni, shumë butë, si një pëshpëritje. «Stacioni i Ëndrrave. Ndalesa e fundit. Të gjithë pasagjerët mund të zbresin.» Dhe Arbi zbriti, në një vend të butë e të ndritshëm, ku retë ishin si jastëkë, ku yjet këndonin dhe ku e prisnin të gjithë lodrat e tij, gati për lojë.$s$,
    $s$Treni i vogël blu u kthye ngadalë drejt stacionit të yjeve, me fenerin e kuq që shkëlqente në fund. Nesër në mbrëmje do të kthehet përsëri, për Arbin dhe për të gjithë fëmijët e qytetit. Ndoshta edhe për ty. Tani, a e dëgjon? Tut-tut. Është koha. Mbylli sytë. Natën e mirë.$s$
  ]::text[],
  array['sleep']::text[], 0, 60, 9, 'moon',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gtreniigjumit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gtreniigjumit)"/><circle cx="121" cy="31.3" r="1.5" fill="#F3EBD9" opacity="0.7"/><circle cx="119.1" cy="43.2" r="1.6" fill="#F3EBD9" opacity="0.7"/><circle cx="128.7" cy="33.2" r="1.4" fill="#F3EBD9" opacity="0.7"/><path d="M9.3 4.9Q9.3 7.9 12.3 7.9Q9.3 7.9 9.3 10.9Q9.3 7.9 6.300000000000001 7.9Q9.3 7.9 9.3 4.9Z" fill="#F3EBD9" opacity="0.9"/><circle cx="16.6" cy="29.3" r="0.9" fill="#F3EBD9" opacity="0.7"/><circle cx="110" cy="39" r="1.4" fill="#F3EBD9" opacity="0.7"/><circle cx="27.1" cy="22" r="11" fill="#F3EBD9"/><circle cx="33.1" cy="18" r="10" fill="#1E3446"/><path d="M0 90.5Q40 80.7 80 90.7T160 85.4V120H0Z" fill="#24455A"/><path d="M0 101.8Q40 89.7 80 97.7T160 97.9V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><rect x="4" y="30" width="26" height="20" rx="2" fill="#F3EBD9"/><rect x="10" y="18" width="14" height="14" rx="2" fill="#F3EBD9"/><rect x="30" y="22" width="10" height="28" rx="2" fill="#F3EBD9"/><rect x="42" y="30" width="20" height="20" rx="2" fill="#E7B04B"/><circle cx="12" cy="52" r="6" fill="#F3EBD9"/><circle cx="26" cy="52" r="6" fill="#F3EBD9"/><circle cx="52" cy="52" r="5" fill="#F3EBD9"/><circle cx="12" cy="52" r="2" fill="#24455A"/><circle cx="26" cy="52" r="2" fill="#24455A"/><circle cx="52" cy="52" r="2" fill="#24455A"/><rect x="46" y="34" width="5" height="5" rx="1" fill="#24455A"/><rect x="54" y="34" width="5" height="5" rx="1" fill="#24455A"/><rect x="33" y="26" width="5" height="6" rx="1" fill="#24455A"/><circle cx="14" cy="10" r="4" fill="#F3EBD9" opacity="0.4"/><circle cx="8" cy="4" r="3" fill="#F3EBD9" opacity="0.3"/><path d="M4 48L0 56H8Z" fill="#F3EBD9"/></g></svg>$s$,
  'published', true, 210, 'editor'
),
(
  $s$gjysmagjeli$s$, 'sq', $s$Gjysmagjeli$s$,
  $s$Përrallë popullore shqiptare: një gjel me një këmbë dhe një krah shkon vetë te mbreti për të marrë florinë e plakës, me tre miq të çuditshëm nën krah.$s$,
  array[
    $s$Na ishte një herë një plakë e varfër, që jetonte në fund të një fshati, në një shtëpi të vogël me çati prej rrase. Plaka s'kishte as lopë, as dhi, as pula. Kishte vetëm një gjel. Por edhe ai s'ishte gjel i plotë: kishte një këmbë, një krah dhe një sy. Prandaj në fshat e thërrisnin Gjysmagjeli.$s$,
    $s$Gjysmagjeli ishte i vogël, por kishte zemër të madhe. Çdo mëngjes, para se të dilte dielli, kërcente mbi gardh me të vetmen këmbë dhe këndonte aq fort, sa zgjoheshin të gjithë fshatarët: «Kikiriki! Zgjohuni, se dielli po vjen!»$s$,
    $s$Një ditë, duke gërmuar me këmbë në pluhurin e oborrit, Gjysmagjeli gjeti diçka që shkëlqente. Ishte një flori i artë, i rrumbullakët si një diell i vogël. «Gjyshe, gjyshe!» thirri ai. «Tani do të blejmë miell për bukë dhe lesh për çorape!»$s$,
    $s$Por pikërisht atë çast kaloi aty pranë karroca e mbretit. Mbreti pa florinë që shkëlqente, zgjati dorën nga dritarja dhe tha: «Ky flori është i imi. Gjithë ari i këtij vendi është i imi.» E futi florinë në xhep dhe karroca iku, duke lënë pas vetëm pluhur.$s$,
    $s$Plaka u ul në prag dhe psherëtiu. Por Gjysmagjeli e ngriti kokën lart. «Mos u mërzit, gjyshe. Do të shkoj te mbreti dhe do ta kërkoj florinë tonë. Ajo që është e drejtë, është e drejtë.» Dhe u nis, hop-hop, me një këmbë, në rrugën e madhe.$s$,
    $s$Kishte bërë pak rrugë, kur doli para tij një dhelpër. «Ku po shkon, o Gjysmagjel?» «Te mbreti, të marr florinë tim.» «Më merr edhe mua me vete», tha dhelpra, «se ndoshta të duhem.» «Hajde, hyr nën krahun tim», tha Gjysmagjeli. Dhelpra u bë e vogël, e vogël, dhe u fsheh nën krahun e tij.$s$,
    $s$Më tej doli një ujk. «Ku po shkon, o Gjysmagjel?» «Te mbreti, të marr florinë tim.» «Më merr edhe mua, se ndoshta të duhem.» «Hajde, hyr nën krah.» Dhe ujku u bë i vogël si një lëmsh leshi dhe u fsheh pranë dhelprës.$s$,
    $s$Pastaj arriti te një lumë i madh, që rridhte me zhurmë mes gurëve. «Ku po shkon, o Gjysmagjel?» gurgulloi lumi. «Te mbreti, të marr florinë tim.» «Më merr edhe mua, se ndoshta të duhem.» Gjysmagjeli hapi krahun dhe lumi, pikë pas pike, u fut aty, i qetë si një pellg i vogël.$s$,
    $s$Më në fund arriti te pallati i mbretit. Trokiti me sqep në portën e madhe: tak, tak, tak. «Mbret, o mbret! Ma kthe florinë që më more!» Mbreti doli në ballkon, e pa këtë gjel me një këmbë dhe qeshi me të madhe. «Hidheni te kotecet», urdhëroi. «Gjelat e mi të mëdhenj do ta mësojnë si flitet me mbretin.»$s$,
    $s$E futën në kotec. Gjelat e mbretit, të mëdhenj e mburravecë, u turrën drejt tij me pendët ngritur. Por Gjysmagjeli hapi krahun: «Dil, dhelpër, se tani të dua!» Dhelpra kërceu jashtë dhe gjelat ikën me vrap e me britma, deri në fund të kopshtit. Dhelpra nuk kapi asnjë, vetëm i trembi. Por kotecin e la bosh.$s$,
    $s$Të nesërmen mbreti tha: «Futeni në ahur, mes kuajve. Le ta mësojnë ata.» Por Gjysmagjeli hapi krahun: «Dil, ujk, se tani të dua!» Ujku doli dhe ulëriu një herë: auuu! Kuajt hingëllinë, shtynë derën dhe ikën me galop nëpër fusha. Ahuri mbeti bosh dhe stallierët vrapuan pas tyre deri në mbrëmje.$s$,
    $s$Mbreti u nxeh edhe më shumë. «Ndizni zjarrin e madh në kuzhinë dhe afrojeni aty, sa të nxehet e të heqë dorë!» Por para se ta afronin, Gjysmagjeli hapi krahun: «Dil, lumë, se tani të dua!» Lumi u derdh me zhurmë, e shoi zjarrin me një frymë, e mbushi kuzhinën me ujë deri në gju, dhe kuzhinierët u ngjitën mbi tryeza me kapelet në dorë.$s$,
    $s$Mbreti, i lodhur dhe me këpucët e lagura, u ul në fron dhe tha: «Çfarë gjeli është ky? Nuk i trembet as gjelave, as kuajve, as zjarrit!» Pastaj urdhëroi: «Çojeni në thesar. Le ta marrë florinë e vet dhe të ikë, që të mos e shoh më!»$s$,
    $s$Në thesar kishte arka plot me flori. Gjysmagjeli e gjeti menjëherë florinë e tij, sepse e njihte nga një gërvishtje e vogël që i kishte bërë me thua. E mori. Pastaj kujtoi fshatin e tij, ku dimri ishte i gjatë dhe shumë shtëpi s'kishin miell. «Mbret», thirri, «më more florinë dhe më bëre tri ditë të vështira. Për çdo ditë, më jep nga një flori për fshatin tim.» Mbreti, që donte vetëm ta shihte të ikte, tundi dorën: «Merri, merri dhe shko!»$s$,
    $s$Kështu Gjysmagjeli u kthye në shtëpi, hop-hop, me katër flori nën krah. Dhelpra, ujku dhe lumi e përcollën deri te ura e fshatit. Aty u ndanë si miq të vjetër: dhelpra shkoi në pyll, ujku në mal dhe lumi u kthye në shtratin e vet, duke kënduar mes gurëve.$s$,
    $s$Plaka, kur e pa, qau nga gëzimi. Me florinë e parë bleu miell, me të dytin lesh, me të tretin dru për dimër, dhe të katërtin ia dha mullixhiut, që të bluante grurë për të gjithë fshatin. Atë mbrëmje, nga çdo oxhak dilte tym dhe në çdo shtëpi kishte bukë të ngrohtë.$s$,
    $s$Dhe që nga ajo ditë, kur dikush në fshat thoshte «Je i vogël, s'mund të bësh asgjë», plaka buzëqeshte dhe tregonte me gisht nga gardhi, ku Gjysmagjeli këndonte me të vetmen këmbë: «Kikiriki! I vogël është trupi, e madhe është zemra!»$s$
  ]::text[],
  array['classic', 'adventure']::text[], 36, 108, 12, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="ggjysmagjeli" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BBDAE4"/><stop offset="1" stop-color="#EAF4F2"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#ggjysmagjeli)"/><circle cx="129.3" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="34" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="30" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="39" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 84.9Q40 69.2 80 81.2T160 84.1V120H0Z" fill="#A6CDB4"/><path d="M0 99.4Q40 93.2 80 101.2T160 103.7V120H0Z" fill="#86B897"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M20 38Q2 32 4 12Q12 26 18 28Q8 16 14 4Q20 22 24 30Z" fill="#35504B"/><circle cx="28" cy="42" r="14" fill="#35504B"/><path d="M34 34L40 22L48 24L44 38Z" fill="#35504B"/><circle cx="44" cy="22" r="7" fill="#35504B"/><path d="M50 21L57 23L50 25Z" fill="#E07B5F"/><circle cx="39" cy="15" r="3" fill="#E07B5F"/><circle cx="43" cy="13" r="3.2" fill="#E07B5F"/><circle cx="47" cy="15" r="2.8" fill="#E07B5F"/><ellipse cx="49" cy="29" rx="2" ry="3" fill="#E07B5F"/><circle cx="46" cy="20" r="1.4" fill="#EAF4F2"/><path d="M28 55L28 60" fill="none" stroke="#E07B5F" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', true, 220, 'editor'
),
(
  $s$tre-derrkucat$s$, 'sq', $s$Tre derrkucët$s$,
  $s$Tre vëllezër derrkuc ndërtojnë secili shtëpinë e vet: me kashtë, me degë dhe me tulla. Kur vjen ujku, kuptojnë pse puna e mirë kërkon kohë.$s$,
  array[
    $s$Na ishin një herë tre derrkucë vëllezër, rozë e të rrumbullakët, që jetonin me nënën e tyre në një fermë. Një ditë, nëna u tha: «Jeni rritur tani. Është koha që secili të ndërtojë shtëpinë e vet. Por mbani mend: ndërtojeni mirë, sepse në pyll jeton ujku.»$s$,
    $s$Derrkuci i parë ishte më dembeli. Pa një fshatar që po mblidhte kashtë dhe i tha: «Më jep pak kashtë, të lutem, se dua të ndërtoj shtëpi.» Fshatari i dha. Derrkuci e grumbulloi kashtën, e lidhi me pe dhe në një orë shtëpia ishte gati. «Mbarova!» tha dhe u shtri në diell. «Tani mund të luaj gjithë ditën.»$s$,
    $s$Derrkuci i dytë ishte pak më i zellshëm. Mblodhi degë të thata në skajin e pyllit, i lidhi me fije bari dhe ndërtoi një shtëpi me dru. I mori një pasdite të tërë. «Mbarova!» tha. «Kjo është më e fortë se ajo e kashtës. Tani mund të luaj edhe unë.»$s$,
    $s$Derrkuci i tretë ishte më i durueshmi. Shkoi te një murator dhe mori tulla të kuqe, rërë dhe gëlqere. Ndërtoi muret tullë pas tulle, bëri çatinë me tjegulla, bëri një oxhak të fortë dhe një derë prej lisi. I mori shumë ditë. Vëllezërit e tij vinin dhe qeshnin: «Hajde të luajmë! Pse lodhesh kaq shumë?» «Sepse dua një shtëpi që të më mbrojë», thoshte ai, dhe vazhdonte punën.$s$,
    $s$Një mëngjes, nga pylli doli ujku. Kishte uri dhe nuhati erën e derrkucëve. Shkoi i pari te shtëpia prej kashte dhe trokiti. «Derrkuc, derrkuc, më hap derën!» «Jo, për asnjë qime të mjekrës sime!» bërtiti derrkuci. «Atëherë do të fryj e do të shfryj, dhe shtëpinë do ta rrëzoj!» tha ujku.$s$,
    $s$Dhe ujku mori frymë thellë, fryu e shfryu: fuuuuu! Shtëpia prej kashte u shpërnda në ajër si push luleradhiqeje. Derrkuci i parë vrapoi me sa i hanin këmbët deri te shtëpia prej druri e vëllait të dytë dhe hyri brenda, duke mbyllur derën pas vetes.$s$,
    $s$Ujku i shkoi pas. «Derrkucë, derrkucë, më hapni derën!» «Jo, për asnjë qime të mjekrës sonë!» «Atëherë do të fryj e do të shfryj, dhe shtëpinë do ta rrëzoj!» Ujku mori frymë edhe më thellë, fryu e shfryu: fuuuuuuu! Degët u shkëputën njëra pas tjetrës dhe shtëpia ra përtokë. Dy derrkucët ikën me vrap te shtëpia prej tullash e vëllait të tretë.$s$,
    $s$«Hyni shpejt!» tha vëllai i tretë dhe e mbylli derën e rëndë prej lisi. Ujku arriti te dera. «Derrkucë, derrkucë, më hapni derën!» «Jo, për asnjë qime të mjekrës sonë!» «Atëherë do të fryj e do të shfryj, dhe shtëpinë do ta rrëzoj!»$s$,
    $s$Ujku fryu. Fryu edhe më fort. Fryu deri sa iu skuqën faqet, iu zgurdulluan sytë e iu ngatërrua gjuha. Por shtëpia prej tullash nuk lëvizi as edhe një milimetër. Brenda, tre derrkucët dëgjonin fryrjet dhe mbanin frymën, me sytë nga dera.$s$,
    $s$Ujku u ul përtokë i rraskapitur. Pastaj ngriti sytë dhe pa oxhakun. «Aha», mendoi, «do të hyj nga lart.» U ngjit në çati dhe filloi të zbriste nëpër oxhak. Por derrkuci i tretë e kishte dëgjuar. Hodhi shpejt dru në vatër dhe ndezi një zjarr të madh, me flakë të verdha e tym të dendur.$s$,
    $s$Kur ujku zbriti në oxhak dhe ndjeu nxehtësinë e flakës dhe tymin në hundë, u ngjit lart me një kërcim, kollitej e teshtinte, me bishtin e nxirë nga bloza. Kërceu nga çatia dhe vrapoi drejt pyllit, aq shpejt sa u zhduk si era. Dhe s'u kthye më kurrë, se që nga ajo ditë kishte frikë edhe nga oxhaqet më të vegjël.$s$,
    $s$Tre vëllezërit dolën në oborr dhe u përqafuan. Dy të parët ulën kokën. «Ti kishe të drejtë», i thanë vëllait të tretë. «Ne kërkonim vetëm mënyrën më të shpejtë.» «S'ka gjë», tha ai. «Tani e dini. Dhe nëse doni, do t'ju ndihmoj të ndërtoni shtëpi prej tullash edhe ju.»$s$,
    $s$Dhe kështu bënë. Punuan të tre bashkë, tullë pas tulle, dhe pas disa javësh, në skaj të fermës kishte tri shtëpi të forta me oxhakë që nxirrnin tym. Çdo mbrëmje, derrkucët hanin darkë bashkë, në njërën shtëpi apo në tjetrën, dhe flinin të qetë, sepse e dinin që muret e tyre ishin të forta. Dhe nëna e tyre, kur i vizitonte, buzëqeshte me krenari.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 0, 72, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gtrederrkucat" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gtrederrkucat)"/><circle cx="129.5" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="34" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="30" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="39" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 82.6Q40 77.5 80 89.5T160 89V120H0Z" fill="#B5D39A"/><path d="M0 99Q40 95.2 80 103.2T160 101.2V120H0Z" fill="#93BE7B"/><circle cx="116.2" cy="114.3" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="13.4" cy="113.5" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="24.1" cy="110" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="148.2" cy="105.1" r="1.6" fill="#E7B04B" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="28" cy="42" rx="20" ry="13" fill="#3E5A38"/><circle cx="48" cy="35" r="10" fill="#3E5A38"/><ellipse cx="57" cy="37" rx="4.5" ry="4" fill="#E58C5A"/><circle cx="56" cy="36.5" r="0.9" fill="#F4F7EA"/><circle cx="58.5" cy="37.5" r="0.9" fill="#F4F7EA"/><path d="M42 27L44 19L49 26Z" fill="#3E5A38"/><path d="M49 26L54 20L55 28Z" fill="#3E5A38"/><circle cx="50" cy="32" r="1.3" fill="#F4F7EA"/><rect x="14" y="48" width="6" height="12" rx="3" fill="#3E5A38"/><rect x="34" y="48" width="6" height="12" rx="3" fill="#3E5A38"/><path d="M8 38q-5 -2 -3 -6q3 -2 3 2" fill="none" stroke="#3E5A38" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 230, 'editor'
),
(
  $s$fenerxhiu-i-yjeve$s$, 'sq', $s$Fenerxhiu i yjeve$s$,
  $s$Çdo mbrëmje, një plak me një shkallë të gjatë dhe me një shkrepëse argjendi ngjitet në qiell e ndez yjet një nga një. Një natë i duhet ndihma e një vajze të vogël.$s$,
  array[
    $s$A e ke pyetur ndonjëherë veten kush i ndez yjet çdo mbrëmje? Thonë se diku, në majë të malit më të lartë, ku toka takon qiellin, jeton një plak që quhet Fenerxhiu. Ka mjekër të bardhë e të gjatë, një pallto blu me yje të qëndisur, një shkallë që arrin deri në qiell dhe një shkrepëse të vogël prej argjendi.$s$,
    $s$Çdo mbrëmje, kur dielli fshihet pas detit e qielli bëhet blu i errët, Fenerxhiu e mbështet shkallën pas qiellit dhe ngjitet, shkallë pas shkalle. Kur arrin lart, nxjerr shkrepësen e argjendtë, e ndez me një shkëndijë dhe e afron te ylli i parë. Ylli ndizet: ping! Pastaj shkon te ylli i dytë: ping! Te i treti: ping! Dhe kështu me radhë, gjithë natën, derisa i gjithë qielli shkëlqen.$s$,
    $s$Fenerxhiu i njeh të gjithë yjet me emër. Ylli i Mbrëmjes, që ndizet i pari dhe shkëlqen më shumë se të tjerët. Arusha e Madhe, me shtatë yjet e saj në formë kove. Ylli Polar, që nuk lëviz kurrë dhe u tregon udhëtarëve rrugën. Dhe mijëra yje të vegjël, që s'kanë emër, por që Fenerxhiu i do njësoj.$s$,
    $s$Por Fenerxhiu po plakej. Këmbët i dhembnin pak më shumë çdo mbrëmje, dhe shkalla i dukej pak më e gjatë. Një natë dimri, kur era ishte e ftohtë dhe qielli shumë i madh, Fenerxhiu u ngjit me vështirësi deri në mes të shkallës dhe ndaloi. «Nuk po arrij dot», tha me vete. «Sonte, shumë yje do të mbeten të fikur.»$s$,
    $s$Poshtë, në një fshat në këmbët e malit, jetonte një vajzë e vogël që quhej Ylli. Çdo mbrëmje, para se të flinte, shikonte nga dritarja si ndizeshin yjet. Ishte loja e saj e preferuar: i numëronte ndërsa ndizeshin, një, dy, tre, derisa e zinte gjumi. Por atë natë, numëroi vetëm deri te njëzet, dhe pastaj qielli mbeti i errët, me vrima të zeza mes yjeve.$s$,
    $s$«Diçka nuk shkon», tha Ylli. Veshi pallton e saj të kuqe, mori shallin e leshtë dhe dorezat, dhe doli në heshtje nga shtëpia. Ndoqi shtegun e malit nën dritën e pak yjeve të ndezur, derisa arriti në majë, ku e gjeti Fenerxhiun të ulur në shkallë, me shkrepësen e argjendtë në dorë dhe me kokën ulur.$s$,
    $s$«Pse janë fikur yjet?» e pyeti Ylli. Fenerxhiu ngriti kokën, i habitur që e shihte një fëmijë atje lart. «Jam plakur, vogëlushe», tha. «Shkalla është e gjatë dhe këmbët e mia janë të lodhura. Nuk arrij dot t'i ndez të gjithë.» Ylli u mendua një çast. «Atëherë do të të ndihmoj unë», tha. «Unë kam këmbë të reja.»$s$,
    $s$Fenerxhiu buzëqeshi dhe i dha shkrepësen e argjendtë. «Kujdes», i tha, «afroje butë, mos e nxito. Yjet janë të ndjeshëm.» Dhe Ylli u ngjit në shkallë, shkallë pas shkalle, gjithnjë e më lart, deri sa toka u bë e vogël poshtë saj dhe fshati u duk si një grusht dritash të vogla. Era e ftohtë i fshikullonte faqet, por ajo nuk kishte frikë.$s$,
    $s$Kur arriti lart, Ylli e ndezi shkrepësen dhe e afroi te ylli i parë i fikur. Ping! Ylli u ndez dhe shkëlqeu. Vajza qeshi nga gëzimi. Ping! Ping! Ping! Ylli lëvizte nga një yll te tjetri, ndërsa Fenerxhiu, nga poshtë, ia tregonte me gisht: «Atë atje, pranë Arushës. Atë të voglin, që pothuajse s'duket. Atë që dridhet pak.»$s$,
    $s$Ndezën yje gjithë natën. Yje të mëdhenj e yje të vegjël, yje të bardhë e yje pak të verdhë, yje që shkëlqenin fort e yje që shkëlqenin butë. Dhe kur ylli i fundit u ndez, i gjithë qielli ishte aq i ndritshëm, sa dukej si një fushë me lule drite. Ylli zbriti shkallës dhe u ul pranë Fenerxhiut, e lodhur por e lumtur.$s$,
    $s$«Faleminderit», tha Fenerxhiu. «S'ka qenë kurrë qielli kaq i bukur.» Pastaj nxori nga xhepi i palltos një yll të vogël, të vockël, sa një kokërr gruri, që shkëlqente si xhevahir. «Ky është ylli i fundit që kam ndezur kur isha i ri», tha. «Mbaje. Dhe kur të rritesh pak më shumë, nëse do, mund të vish të më ndihmosh përsëri.»$s$,
    $s$Ylli zbriti nga mali ndërsa qielli fillonte të zbardhej në lindje. U fut në shtëpi pa zhurmë, hoqi pallton e kuqe dhe u fut nën jorgan, me yllin e vogël në grusht. Ishte aq e lodhur, sa e zuri gjumi menjëherë. Dhe në ëndërr, pa veten duke u ngjitur në shkallë të arta, duke ndezur yje të reja, në qiej të panjohur.$s$,
    $s$Thonë se edhe sot, kur sheh qiellin plot me yje, disa prej tyre i ka ndezur Ylli. Dhe se Fenerxhiu, kur është shumë i lodhur, ka gjithmonë një ndihmëse me pallto të kuqe. Sonte, para se të flesh, shiko nga dritarja. Numëroji yjet që shkëlqejnë. Dhe kur të të zërë gjumi, mendo që diku, në majë të malit, dikush i ndez për ty.$s$
  ]::text[],
  array['sleep', 'emotions']::text[], 36, 96, 10, 'star',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gfenerxhiuiyjeve" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gfenerxhiuiyjeve)"/><circle cx="21.1" cy="38.7" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="123.7" cy="22" r="1.6" fill="#F3EBD9" opacity="0.7"/><path d="M90.4 12.5Q90.4 15.5 93.4 15.5Q90.4 15.5 90.4 18.5Q90.4 15.5 87.4 15.5Q90.4 15.5 90.4 12.5Z" fill="#F3EBD9" opacity="0.9"/><circle cx="117.6" cy="23.1" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="30.7" cy="42.4" r="0.8" fill="#F3EBD9" opacity="0.7"/><circle cx="122.9" cy="22" r="11" fill="#F3EBD9"/><circle cx="116.9" cy="18" r="10" fill="#1E3446"/><path d="M0 84.6Q40 81.6 80 91.6T160 91.2V120H0Z" fill="#24455A"/><path d="M0 103Q40 89.1 80 97.1T160 99.5V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 0V8" fill="none" stroke="#F3EBD9" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/><path d="M24 8H40L42 14H22Z" fill="#F3EBD9"/><rect x="22" y="14" width="20" height="26" rx="3" fill="#E7B04B" opacity="0.95"/><circle cx="32" cy="27" r="6" fill="#FFFFFF" opacity="0.7"/><path d="M22 14L22 40M42 14L42 40M32 14L32 40" fill="none" stroke="#F3EBD9" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><path d="M20 40H44L40 46H24Z" fill="#F3EBD9"/><circle cx="32" cy="27" r="18" fill="#E7B04B" opacity="0.18"/></g></svg>$s$,
  'published', false, 240, 'editor'
),
(
  $s$flokeartja-dhe-tre-arinjte$s$, 'sq', $s$Flokëartja dhe tre arinjtë$s$,
  $s$Një vajzë kurioze hyn në shtëpinë e tre arinjve kur ata s'janë aty. Provon qullin, karriget dhe shtretërit, dhe pastaj mëson si kërkohet falje.$s$,
  array[
    $s$Në një shtëpi të vogël druri, në mes të pyllit, jetonin tre arinj: Babai Ari, i madh e me zë të thellë; Mamaja Arushë, e mesme e me zë të butë; dhe Arushi i Vogël, i vockël e me zë të hollë. Shtëpia e tyre kishte perde me lule, një oxhak prej guri dhe tri dritare të rrumbullakëta.$s$,
    $s$Një mëngjes, Mamaja Arushë gatoi qull me tërshërë për mëngjes dhe e hodhi në tri tasa: një tas të madh për Babain Ari, një tas të mesëm për veten dhe një tas të vogël për Arushin e Vogël. Por qulli ishte shumë i nxehtë. «Le të dalim për një shëtitje të vogël», tha Babai Ari, «sa të ftohet.» Dhe dolën të tre në pyll.$s$,
    $s$Në atë pyll, pak më larg, jetonte një vajzë e vogël me flokë të verdhë kaçurrelë, që shkëlqenin si ari. Të gjithë e thërrisnin Flokëartja. Ishte e mirë, por shumë kurioze, dhe atë mëngjes, duke ndjekur një flutur, arriti te shtëpia e arinjve. Dera ishte e hapur. «Ka njeri?» thirri. Askush s'u përgjigj. Dhe Flokëartja hyri.$s$,
    $s$Në tryezë pa tri tasa me qull. Kishte erë aq të mirë sa iu zgjua uria. Provoi qullin e tasit të madh. «Uf, shumë i nxehtë!» Provoi qullin e tasit të mesëm. «Uf, shumë i ftohtë!» Provoi qullin e tasit të vogël. «Mmm, pikërisht siç duhet!» Dhe e hëngri të gjithin, deri në pikën e fundit.$s$,
    $s$Pastaj pa pranë oxhakut tri karrige. U ul në karrigen e madhe. «Shumë e fortë!» U ul në karrigen e mesme. «Shumë e butë!» U ul në karrigen e vogël. «Pikërisht siç duhet!» Por karrigia ishte e vogël, dhe Flokëartja u lëkund pak, pak më shumë, dhe krak! Njëra këmbë e karriges u thye dhe Flokëartja ra me të ndenjur në dysheme.$s$,
    $s$Ishte lodhur tani dhe iu kujtua që kishte zgjuar herët. U ngjit shkallëve dhe gjeti dhomën e gjumit, me tre shtretër. U shtri në shtratin e madh. «Shumë i fortë!» U shtri në shtratin e mesëm. «Shumë i butë!» U shtri në shtratin e vogël. «Pikërisht siç duhet.» Dhe e zuri gjumi menjëherë, me flokët e verdhë të shpërndarë mbi jastëk.$s$,
    $s$Pak më vonë, tre arinjtë u kthyen nga shëtitja. Babai Ari pa tasin e tij. «Dikush ka ngrënë nga qulli im!» tha me zërin e tij të thellë. «Dikush ka ngrënë nga qulli im!» tha Mamaja Arushë me zërin e saj të butë. «Dikush ka ngrënë nga qulli im», tha Arushi i Vogël me zërin e tij të hollë, «dhe e ka mbaruar të gjithin!»$s$,
    $s$Pastaj panë karriget. «Dikush është ulur në karrigen time!» «Dikush është ulur në karrigen time!» «Dikush është ulur në karrigen time», qau Arushi i Vogël, «dhe e ka thyer!» Të tre u ngjitën ngadalë shkallëve. «Dikush ka fjetur në shtratin tim!» «Dikush ka fjetur në shtratin tim!» «Dikush ka fjetur në shtratin tim», pëshpëriti Arushi i Vogël, «dhe është ende këtu!»$s$,
    $s$Flokëartja u zgjua nga zërat. Hapi sytë dhe pa tre arinj që e shikonin: një të madh, një të mesëm dhe një të vogël. U tremb aq shumë, sa u hodh nga shtrati, zbriti shkallët me vrap dhe iku nga dera, nëpër pyll, deri në shtëpinë e saj. Arinjtë mbetën të habitur, sepse në të vërtetë nuk kishin dashur ta trembnin.$s$,
    $s$Atë natë, Flokëartja nuk mund të flinte. Mendonte për qullin që kishte ngrënë, për karrigen e thyer dhe për Arushin e Vogël që kishte qarë. «Kam hyrë në shtëpinë e dikujt pa leje», i tha nënës. «Dhe kam prishur gjëra që s'ishin të miat.» Nëna e dëgjoi dhe i tha: «Atëherë e di çfarë duhet të bësh.»$s$,
    $s$Të nesërmen, Flokëartja u ngrit herët. Me ndihmën e nënës, gatoi një tavë me ëmbëlsirë me mollë dhe arra. Pastaj mori nga hambari një çekiç, gozhdë dhe një copë dru. Dhe u nis drejt shtëpisë së arinjve, këtë herë duke ecur ngadalë, me zemrën që i rrihte fort.$s$,
    $s$Trokiti në derë. Kur Babai Ari e hapi, Flokëartja tha me zë të dridhur: «Më falni. Hyra në shtëpinë tuaj pa leje, hëngra qullin e Arushit të Vogël dhe i theva karrigen. Kam sjellë një ëmbëlsirë dhe dua të ndihmoj ta rregullojmë karrigen.» Arinjtë u shikuan me njëri-tjetrin. Pastaj Mamaja Arushë buzëqeshi. «Hyr, vogëlushe. Këtë herë me leje.»$s$,
    $s$Gjithë mëngjesin, Flokëartja dhe Arushi i Vogël rregulluan karrigen bashkë, me ndihmën e Babait Ari, që mbante dërrasën. Pastaj u ulën të katër rreth tryezës dhe hëngrën ëmbëlsirën me mollë, që doli pikërisht siç duhet: as shumë e nxehtë, as shumë e ftohtë. Dhe që nga ajo ditë, Flokëartja dhe Arushi i Vogël u bënë miq, dhe ajo hynte në shtëpinë e tyre shpesh, por gjithmonë duke trokitur më parë.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 0, 72, 10, 'bear',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gflokeartjadhetrearin" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gflokeartjadhetrearin)"/><circle cx="11.9" cy="75.4" r="16.4" fill="#8FB5A0" opacity="0.85"/><path d="M20.5 42.3L30.5 100H10.5Z" fill="#8FB5A0" opacity="0.85"/><circle cx="35.2" cy="80" r="13.4" fill="#8FB5A0" opacity="0.85"/><path d="M46 51.4L56 100H36Z" fill="#8FB5A0" opacity="0.85"/><path d="M114.6 56.4L124.6 100H104.6Z" fill="#5F8C76" opacity="0.85"/><path d="M132.8 50.8L142.8 100H122.8Z" fill="#8FB5A0" opacity="0.85"/><path d="M147.5 54.1L157.5 100H137.5Z" fill="#5F8C76" opacity="0.85"/><path d="M0 97.6Q40 92.9 80 98.9T160 101.7V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="28" cy="40" rx="20" ry="14" fill="#2C463B"/><circle cx="48" cy="28" r="10" fill="#2C463B"/><circle cx="42" cy="19" r="4" fill="#2C463B"/><circle cx="54" cy="19" r="4" fill="#2C463B"/><circle cx="42" cy="19" r="1.8" fill="#EDF3EC" opacity="0.6"/><circle cx="54" cy="19" r="1.8" fill="#EDF3EC" opacity="0.6"/><ellipse cx="56" cy="31" rx="5.5" ry="4" fill="#2C463B"/><circle cx="60" cy="30" r="1.8" fill="#EDF3EC"/><path d="M49 25.5q2 1.6 4 0" fill="none" stroke="#EDF3EC" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/><rect x="12" y="44" width="8" height="16" rx="4" fill="#2C463B"/><rect x="34" y="44" width="8" height="16" rx="4" fill="#2C463B"/></g></svg>$s$,
  'published', false, 250, 'editor'
),
(
  $s$delja-e-njeqindte$s$, 'sq', $s$Delja e njëqindtë$s$,
  $s$Kur Lira s'fle dot, numëron dele që kërcejnë gardhin. Por delja e njëqindtë ndalon para gardhit dhe s'kërcen dot, dhe Lira duhet ta ndihmojë.$s$,
  array[
    $s$Ishte vonë, por Lira ende s'flinte. Kishte provuar gjithçka. Ishte kthyer në krahun e majtë, pastaj në të djathtin, pastaj me fytyrë nga tavani. Kishte numëruar lulet e perdes. Kishte dëgjuar orën e kuzhinës: tik-tak, tik-tak. Por gjumi nuk vinte.$s$,
    $s$«Numëro dele», i kishte thënë gjyshja dikur. «Mbyll sytë dhe imagjino një fushë të gjelbër me një gardh të vogël druri. Pastaj numëro delet që e kërcejnë, njëra pas tjetrës. Para se të arrish te e njëqindta, do të të zërë gjumi.» Lira mbylli sytë dhe provoi.$s$,
    $s$Imagjinoi një fushë të gjelbër, nën dritën e hënës, me lule të bardha që shkëlqenin. Në mes të fushës ishte një gardh i ulët druri. Dhe nga ana e majtë, erdhi delja e parë: e bardhë, e rrumbullakët, me lesh si re. Bëri disa hapa, mori vrull dhe kërceu mbi gardh: hop! «Një», numëroi Lira.$s$,
    $s$Pastaj erdhi delja e dytë. Hop! «Dy.» Delja e tretë kishte një fjongo të kuqe në vesh. Hop! «Tre.» Delja e katërt ishte pak e trashë dhe mezi kaloi, por kaloi. «Katër.» Delja e pestë ishte aq e gëzuar, sa bëri një rrotullim në ajër. «Pesë.» Dhe kështu me radhë, njëra pas tjetrës, delet kërcenin e Lira numëronte, gjithnjë e më ngadalë.$s$,
    $s$Dhjetë. Njëzet. Tridhjetë e tre, që kishte një zile të vogël në qafë. Pesëdhjetë, që kërceu me një qengj të vogël në shpinë. Shtatëdhjetë. Nëntëdhjetë. Sytë e Lirës ishin të rëndë tani, dhe numrat i dilnin gjithnjë e më të ngadaltë. Nëntëdhjetë e tetë. Nëntëdhjetë e nëntë. Dhe pastaj erdhi delja e njëqindtë.$s$,
    $s$Ishte më e vogla nga të gjitha, një qengj i bardhë me një njollë të zezë rreth syrit. Vrapoi drejt gardhit, mori vrull dhe... ndaloi. Pikërisht para gardhit. Shikoi gardhin, shikoi qiellin, pastaj u ul në bar dhe uli kokën. Nuk kërceu.$s$,
    $s$Lira, me sytë mbyllur, u habit. «Pse s'kërcen?» pyeti me zë të ulët. Dhe qengji, për çudi, iu përgjigj: «Kam frikë. Gardhi më duket shumë i lartë. Të gjitha delet e tjera janë më të mëdha se unë. Po të rrëzohem? Po të mos ia dal?»$s$,
    $s$Lira e kuptoi shumë mirë atë ndjenjë. Edhe ajo kishte pasur frikë herë të tjera: ditën e parë në kopsht, kur u ngjit për herë të parë në rrëshqitësen e madhe, kur provoi biçikletën pa rrota anësore. «Edhe mua më ka ndodhur», i tha qengjit. «A do të të ndihmoj?»$s$,
    $s$Lira, në ëndrrën e saj gjysmë të zgjuar, hyri në fushë. Bari ishte i butë nën këmbët e saj të zbathura dhe ajri kishte erë tërfili. U ul pranë qengjit dhe e përkëdheli në kokë. «Le ta bëjmë së bashku», i tha. «Unë do të numëroj, dhe ti do të kërcesh kur të jesh gati. Jo më parë.»$s$,
    $s$Qengji u ngrit. Lira filloi të numëronte ngadalë: «Një... dy...» Qengji mori frymë thellë. «...tre!» Qengji vrapoi, mori vrull dhe kërceu. Ishte një kërcim i vogël, i ngatërruar, me këmbët e pasme që prekën pak gardhin. Por kaloi! U ul në anën tjetër, në bar, dhe u kthye nga Lira me sytë që i shkëlqenin. «E bëra!»$s$,
    $s$Në anën tjetër të gardhit, të gjitha delet e tjera e prisnin. Nëntëdhjetë e nëntë dele, që blegërinin të gëzuara dhe që e përqafuan qengjin e vogël me leshin e tyre të butë. Pastaj, të gjitha bashkë, u shtrinë në bar, njëra pranë tjetrës, si një re e madhe e bardhë mbi fushën e gjelbër, dhe mbyllën sytë.$s$,
    $s$«Njëqind», pëshpëriti Lira. Dhe ndjeu sytë e saj që ishin bërë të rëndë si plumb, dhe krahët që ishin bërë të butë si leshi. Ndjeu jastëkun nën faqe dhe jorganin mbi supe. Ora e kuzhinës bënte tik-tak, tik-tak, por tani tingëllonte si një ninullë.$s$,
    $s$Lira nuk numëroi më. Ishte në fushën e gjelbër, me njëqind dele të fjetura, me hënën që ndriçonte mbi to, dhe me qengjin e vogël me njollë të zezë që i flinte pranë, me kokën mbi dorën e saj. Dhe kështu, më në fund, Lirën e zuri gjumi. Natën e mirë, Lira. Natën e mirë, njëqind dele. Natën e mirë, qengj i vogël që kërceve.$s$
  ]::text[],
  array['sleep', 'emotions']::text[], 0, 72, 9, 'lamb',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gdeljaenjeqindte" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gdeljaenjeqindte)"/><path d="M112.1 33.300000000000004Q112.1 36.6 115.39999999999999 36.6Q112.1 36.6 112.1 39.9Q112.1 36.6 108.8 36.6Q112.1 36.6 112.1 33.300000000000004Z" fill="#F3EBD9" opacity="0.9"/><circle cx="72.7" cy="14" r="1" fill="#F3EBD9" opacity="0.7"/><circle cx="13.8" cy="34.3" r="1.4" fill="#F3EBD9" opacity="0.7"/><circle cx="11" cy="16.4" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="127" cy="41.1" r="1" fill="#F3EBD9" opacity="0.7"/><path d="M117.7 23.1Q117.7 25.6 120.2 25.6Q117.7 25.6 117.7 28.1Q117.7 25.6 115.2 25.6Q117.7 25.6 117.7 23.1Z" fill="#F3EBD9" opacity="0.9"/><circle cx="25.7" cy="19" r="1.3" fill="#F3EBD9" opacity="0.7"/><circle cx="128.8" cy="39.6" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="34.7" cy="22" r="11" fill="#F3EBD9"/><circle cx="40.7" cy="18" r="10" fill="#1E3446"/><path d="M0 89.5Q40 82.9 80 92.9T160 90V120H0Z" fill="#24455A"/><path d="M0 98.3Q40 89.3 80 97.3T160 102.1V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><circle cx="18" cy="38" r="9" fill="#F3EBD9"/><circle cx="28" cy="33" r="10" fill="#F3EBD9"/><circle cx="38" cy="35" r="9" fill="#F3EBD9"/><circle cx="24" cy="44" r="9" fill="#F3EBD9"/><circle cx="36" cy="44" r="9" fill="#F3EBD9"/><circle cx="14" cy="44" r="7" fill="#F3EBD9"/><ellipse cx="50" cy="37" rx="6" ry="8" fill="#E7B04B" transform="rotate(20 50 37)"/><ellipse cx="46" cy="31" rx="3.5" ry="2" fill="#E7B04B" transform="rotate(-20 46 31)"/><circle cx="51.5" cy="35" r="1.1" fill="#24455A"/><rect x="18" y="50" width="4" height="10" rx="2" fill="#E7B04B"/><rect x="34" y="50" width="4" height="10" rx="2" fill="#E7B04B"/></g></svg>$s$,
  'published', false, 260, 'editor'
),
(
  $s$hirushja$s$, 'sq', $s$Hirushja$s$,
  $s$Përralla e vajzës që rrinte pranë hirit të vatrës, e një kumbare të mirë me magji dhe e një këpuce kristali që mbeti në shkallët e pallatit.$s$,
  array[
    $s$Na ishte një herë një vajzë e mirë dhe e butë, që e kishte humbur nënën kur ishte e vogël. Babai i saj u martua përsëri me një grua krenare, që kishte dy vajza të saj. Njerka dhe vajzat e saj nuk e donin vajzën. I jepnin të bënte të gjitha punët e rënda të shtëpisë dhe e linin të flinte pranë vatrës, mbi hirin e ngrohtë. Prandaj e thërrisnin Hirushja.$s$,
    $s$Por Hirushja nuk u ankua kurrë. Fshinte, lante, gatuante dhe këndonte me zogjtë që vinin në dritare. Çdo mbrëmje, shkonte në kopsht, te një pemë lajthie që kishte mbjellë nëna e saj, dhe i fliste asaj si t'i fliste nënës.$s$,
    $s$Një ditë, mbreti shpalli një ballo të madhe në pallat, që i biri, princi, të gjente nusen e tij. Të gjitha vajzat e mbretërisë ishin të ftuara. Motrat e njerkës u gëzuan aq shumë sa provuan dhjetë fustane secila dhe bënë Hirushen t'u rregullonte flokët për orë të tëra. «A mund të vij edhe unë?» pyeti Hirushja me zë të ulët. Motrat qeshën. «Ti? Me këto rroba të vjetra e me hirin në fytyrë? Ç'thua!»$s$,
    $s$Natën e ballos, Hirushja mbeti vetëm në shtëpi. U ul në kopsht, nën pemën e lajthisë, dhe qau. Papritur, ajri rreth saj filloi të shkëlqente, si pluhur ari në një rreze dielli, dhe para saj u shfaq një grua e moshuar, me një shkop të hollë në dorë dhe me buzëqeshje të ngrohtë. «Mos qaj, bija ime», tha. «Unë jam kumbara jote e mirë. Dhe ti do të shkosh në ballo.»$s$,
    $s$«Më sill një kungull nga kopshti», tha kumbara. Hirushja i solli kungullin më të madh. Kumbara e preku me shkop dhe kungulli u bë një karrocë e artë, me rrota që shkëlqenin. Pastaj preku gjashtë minj të bardhë që dolën nga kurthi, dhe ata u bënë gjashtë kuaj të bardhë. Preku një mi të madh me mustaqe dhe ai u bë karrocier me kapelë. Preku gjashtë hardhuca të gjelbra dhe ato u bënë shërbëtorë me rroba të gjelbra.$s$,
    $s$Në fund, preku Hirushen me shkop. Rrobat e saj të vjetra u bënë një fustan i kaltër si qielli i mbrëmjes, me yje argjendi të qëndisur. Dhe në këmbë i dolën dy këpucë kristali, të tejdukshme e të ndritshme si akulli në diell. «Shko dhe gëzohu», i tha kumbara. «Por mbaj mend: në mesnatë magjia mbaron. Duhet të kthehesh para se ora të bjerë dymbëdhjetë herë.»$s$,
    $s$Kur Hirushja hyri në sallën e madhe të pallatit, muzika pushoi dhe të gjithë u kthyen ta shikonin. Askush s'e njohu, as njerka, as motrat. Princi u afrua, u përkul dhe e ftoi të kërcente. Dhe kërcyen gjithë mbrëmjen, vetëm ata të dy, ndërsa qirinjtë digjeshin dhe muzika luante. Princi i foli për librat që i pëlqenin, dhe ajo i foli për zogjtë e kopshtit, dhe të dy qeshnin si të njiheshin prej kohësh.$s$,
    $s$Hirushja ishte aq e lumtur, sa harroi orën. Papritur, ora e madhe e kullës filloi të binte: dang, dang, dang. Ishte mesnata! «Duhet të iki!» thirri ajo dhe vrapoi drejt shkallëve. Princi vrapoi pas saj, por ajo ishte shumë e shpejtë. Në shkallët e pallatit, njëra këpucë kristali i shpëtoi nga këmba. Nuk kishte kohë ta merrte.$s$,
    $s$Në goditjen e dymbëdhjetë, karroca u bë përsëri kungull, kuajt u bënë minj, dhe Hirushja u gjend në rrugë, me rrobat e saj të vjetra. Por në këmbë kishte ende njërën këpucë kristali, të vetmen gjë që magjia kishte lënë. E fshehu nën përparëse dhe vrapoi në shtëpi.$s$,
    $s$Princi gjeti këpucën në shkallë dhe e mbajti në duar gjithë natën. Të nesërmen shpalli: «Do të martohem me vajzën që i shkon kjo këpucë.» Dhe dërgoi shërbëtorët e tij në çdo shtëpi të mbretërisë. Çdo vajzë e provoi, por këpuca ishte e vogël për të gjitha. Më në fund arritën te shtëpia e Hirushes. Motrat e njerkës u munduan me gjithë forcën t'i fusnin këmbët, por njërës i doli gishti i madh jashtë, dhe tjetrës thembra.$s$,
    $s$«A ka ndonjë vajzë tjetër në këtë shtëpi?» pyeti princi, që kishte ardhur vetë. «Vetëm shërbëtorja, Hirushja», tha njerka me përbuzje. «Ajo s'ka qenë në ballo.» «Le të vijë», tha princi. Hirushja doli nga kuzhina, me hirin në faqe, u ul dhe vuri këmbën në këpucë. Këpuca i shkoi si të ishte bërë për të. Pastaj nxori nga përparësja këpucën tjetër dhe e vuri në këmbën tjetër.$s$,
    $s$Princi e njohu menjëherë sytë e saj të butë. Motrat dhe njerka mbetën pa fjalë. U turpëruan dhe i kërkuan falje Hirushes për gjithë të keqen që i kishin bërë. Dhe Hirushja, që kishte zemër të mirë, i fali. «Gjithçka ka mbaruar tani», u tha. «Le të fillojmë nga e para.»$s$,
    $s$Hirushja dhe princi u martuan, dhe në dasmën e tyre erdhën të gjithë: mbreti, fshatarët, zogjtë e kopshtit, dhe në një cep, me një buzëqeshje të ngrohtë, edhe një grua e moshuar me një shkop të hollë në dorë. Pema e lajthisë u mbart në kopshtin e pallatit, dhe Hirushja vazhdoi t'i fliste çdo mbrëmje. Sepse e dinte që mirësia, edhe kur të duket se s'e sheh askush, një ditë gjithmonë shkëlqen.$s$
  ]::text[],
  array['classic']::text[], 48, 120, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="ghirushja" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#ghirushja)"/><path d="M30.6 26.799999999999997Q30.6 29.4 33.2 29.4Q30.6 29.4 30.6 32Q30.6 29.4 28 29.4Q30.6 29.4 30.6 26.799999999999997Z" fill="#F3EBD9" opacity="0.9"/><circle cx="117.5" cy="43.4" r="1" fill="#F3EBD9" opacity="0.7"/><circle cx="126.1" cy="41.2" r="1" fill="#F3EBD9" opacity="0.7"/><circle cx="26.5" cy="43.7" r="0.9" fill="#F3EBD9" opacity="0.7"/><circle cx="124.5" cy="41" r="1.2" fill="#F3EBD9" opacity="0.7"/><path d="M40.6 41.4Q40.6 44.5 43.7 44.5Q40.6 44.5 40.6 47.6Q40.6 44.5 37.5 44.5Q40.6 44.5 40.6 41.4Z" fill="#F3EBD9" opacity="0.9"/><circle cx="120.2" cy="28.2" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="26.6" cy="22" r="11" fill="#F3EBD9"/><circle cx="32.6" cy="18" r="10" fill="#1E3446"/><path d="M0 87.5Q40 78.4 80 88.4T160 86V120H0Z" fill="#24455A"/><path d="M0 103.2Q40 93.8 80 101.8T160 96.5V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="32" cy="32" rx="24" ry="18" fill="#E8984A"/><path d="M20 18Q24 32 20 46M32 14V50M44 18Q40 32 44 46" fill="none" stroke="#C9763A" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" opacity="0.8"/><rect x="26" y="24" width="12" height="12" rx="6" fill="#24455A"/><path d="M32 14Q30 6 36 4" fill="none" stroke="#7DA86B" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="14" cy="52" r="8" fill="#F3EBD9"/><circle cx="50" cy="52" r="8" fill="#F3EBD9"/><circle cx="14" cy="52" r="3" fill="#24455A"/><circle cx="50" cy="52" r="3" fill="#24455A"/><path d="M56 6.5Q56 10 59.5 10Q56 10 56 13.5Q56 10 52.5 10Q56 10 56 6.5Z" fill="#E7B04B"/><path d="M8 11.5Q8 14 10.5 14Q8 14 8 16.5Q8 14 5.5 14Q8 14 8 11.5Z" fill="#E7B04B" opacity="0.8"/></g></svg>$s$,
  'published', false, 270, 'editor'
),
(
  $s$djali-dhe-shqiponja$s$, 'sq', $s$Djali dhe shqiponja$s$,
  $s$Legjendë e vjetër shqiptare: një djalë bari mbron një zog shqiponje dhe miqësia e tyre i jep emrin një populli të tërë.$s$,
  array[
    $s$Shumë kohë më parë, kur malet dukeshin edhe më të larta dhe pyjet ishin edhe më të dendur, në një fshat të vogël mes shkëmbinjve jetonte një djalosh bari. Çdo mëngjes nxirrte dhentë në kullotë, me një shkop në dorë dhe një fyell në brez. Ishte i qetë dhe i duruar, dhe u fliste kafshëve si t'u flitej njerëzve.$s$,
    $s$Një ditë vere, ndërsa dhentë kullotnin në një lëndinë, djaloshi dëgjoi një zë të hollë që vinte nga lart, nga një shkëmb i thepisur. Ngriti sytë dhe pa një fole të madhe, të ndërtuar me degë të thata. Brenda saj ishte një zog i vogël shqiponje, me pupla gri e të buta, që thërriste me sa fuqi kishte.$s$,
    $s$«Pse thërret kaq shumë?» mendoi djaloshi. Pastaj e pa: përgjatë shkëmbit po ngjitej ngadalë një gjarpër i madh, drejt folesë. Nëna shqiponjë s'dukej gjëkundi. Kishte fluturuar larg, për t'i gjetur ushqim të voglit.$s$,
    $s$Djaloshi nuk e mendoi gjatë. U kap pas rrënjëve dhe gurëve dhe nisi të ngjitej. Duart i gërvishteshin, këmbët i rrëshqisnin, por ai nuk ndalej. Kur arriti pranë folesë, e goditi shkëmbin me shkop, fort, dhe bërtiti aq shumë, sa gjarpri u tremb, u kthye prapa dhe u zhduk në një të çarë të gurit.$s$,
    $s$Zogu i shqiponjës heshti. Vështronte djaloshin me sy të rrumbullakët, të verdhë si qelibar. «Mos ki frikë», i pëshpëriti djaloshi. «Do të rri këtu derisa të vijë mamaja jote.» U ul në një parmak guri pranë folesë dhe priti, ndërsa dielli zbriste pas maleve.$s$,
    $s$Në muzg, qielli u errësua papritur. Një hije e madhe ra mbi shkëmb: ishte nëna shqiponjë, me krahë aq të gjerë sa dukeshin si dy re. Kur pa një njeri pranë folesë, lëshoi një britmë të fortë dhe u lëshua poshtë. Por zogu i vogël thirri me zërin e tij të hollë, dhe shqiponja ndali në ajër. Pa gjurmët e gjarprit në pluhur, pa shkopin e djaloshit, pa të voglin të qetë e pa asnjë të lënduar. Dhe kuptoi.$s$,
    $s$Shqiponja u ul në cep të folesë dhe e vështroi djaloshin gjatë. Pastaj uli kokën ngadalë, si për ta përshëndetur. Që atë ditë, ata u bënë miq.$s$,
    $s$Sa herë që djaloshi dilte me dhentë, shqiponja fluturonte rrotull mbi të. Kur një ujk afrohej nga pylli, ajo e lajmëronte me një britmë. Kur një stuhi vinte nga deti, ajo e paralajmëronte që herët, dhe djaloshi i kthente dhentë në vathë para se të binte shiu. Zogu i vogël u rrit, dhe kur mësoi të fluturonte, i bënte xhiro mbi kokë djaloshit, si për lojë.$s$,
    $s$Djaloshi mësoi shumë nga shqiponja. Mësoi të shihte larg dhe të vinte re gjërat e vogla. Mësoi të priste me durim dhe të mos trembej nga lartësitë. Dhe mësoi diçka më të rëndësishme se të gjitha: se forca e vërtetë nuk është të sulmosh, por të mbrosh atë që është më i dobët se ti.$s$,
    $s$Kalonin vitet dhe djaloshi u bë burrë. Njerëzit e fshatit i kërkonin këshillë, sepse ishte i urtë dhe i drejtë. Kur dy fqinj grindeshin, ai i dëgjonte të dy. Kur dikush humbiste rrugën në mal, ai e gjente. Dhe gjithmonë, mbi kokën e tij, sillej rrotull një shqiponjë.$s$,
    $s$Fshatarët nisën ta thërrisnin «biri i shqipes», djali i shqiponjës. Edhe fëmijët e tij, dhe fëmijët e fëmijëve të tij, u quajtën po kështu. Dhe me kalimin e kohës, thotë legjenda, njerëzit e atyre maleve e quajtën veten shqiptarë, dhe vendin e tyre Shqipëri, vendi i shqiponjave.$s$,
    $s$Ndoshta kështu ka ndodhur vërtet, ndoshta jo. Por kur të shohësh flamurin kuq e zi me shqiponjën me dy krerë, kujto djaloshin që u ngjit në shkëmb jo për të luftuar, por për të mbrojtur një zog të vogël. Dhe mos harro se zemra e guximshme dhe e mirë është ajo që na bën të fortë.$s$,
    $s$Tani mbylli sytë. Lart në male, në folenë e saj, një shqiponjë po fle me krahët mbi të vegjlit e saj. Natën e mirë, bir i shqipes. Natën e mirë, bijë e shqipes.$s$
  ]::text[],
  array['classic', 'adventure']::text[], 36, 120, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gdjalidheshqiponja" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CADAE8"/><stop offset="1" stop-color="#EFF4F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gdjalidheshqiponja)"/><circle cx="122.5" cy="20" r="8" fill="#FFF3D6"/><path d="M-7.700000000000003 100L32.3 35.599999999999994L72.3 100Z" fill="#A8BCCF"/><path d="M23.299999999999997 50.1L32.3 35.599999999999994L41.3 50.1L36.3 54.9L32.3 48.5L28.299999999999997 54.9Z" fill="#FFFFFF" opacity="0.9"/><path d="M91 100L131 40L171 100Z" fill="#A8BCCF"/><path d="M122 53.5L131 40L140 53.5L135 58L131 52L127 58Z" fill="#FFFFFF" opacity="0.9"/><path d="M40 100L80 57.6L120 100Z" fill="#7F99B0"/><path d="M71 67.1L80 57.6L89 67.1L84 70.3L80 66.1L76 70.3Z" fill="#FFFFFF" opacity="0.9"/><path d="M0 102.6Q40 95.7 80 101.7T160 104.2V120H0Z" fill="#7F99B0"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 28Q18 14 0 16Q12 22 14 28Q6 28 2 34Q16 34 22 37L27 46L32 42L37 46L42 37Q48 34 62 34Q58 28 50 28Q52 22 64 16Q46 14 32 28Z" fill="#2F4357"/><circle cx="32" cy="23" r="5" fill="#2F4357"/><path d="M33 24L38 27L33 28Z" fill="#D9644A"/><circle cx="33.5" cy="22" r="1" fill="#EFF4F8"/><path d="M28 46L32 56L36 46Z" fill="#2F4357"/></g></svg>$s$,
  'published', true, 280, 'editor'
),
(
  $s$balena-qe-kendonte-ninulla$s$, 'sq', $s$Balena që këndonte ninulla$s$,
  $s$Në thellësi të oqeanit, një balenë e madhe gri këndon çdo mbrëmje një ninullë që e dëgjojnë të gjitha krijesat e detit, derisa një natë i humbet zëri.$s$,
  array[
    $s$Në mes të oqeanit të madh, aty ku uji është aq i thellë sa drita e diellit s'arrin dot në fund, jetonte një balenë e madhe gri. Quhej Bora. Ishte e madhe sa një anije, me një bisht si dy krahë të gjerë e me sy të vegjël, të butë e të urtë. Dhe Bora kishte diçka të veçantë: zërin më të bukur të gjithë detit.$s$,
    $s$Çdo mbrëmje, kur dielli zbriste në horizont dhe deti bëhej i kuq e pastaj blu i errët, Bora notonte në mes të oqeanit, merrte frymë thellë në sipërfaqe dhe zhytej ngadalë poshtë. Dhe atëherë fillonte të këndonte. Kënga e saj ishte e thellë, e gjatë e e ngadaltë, si zhurma e valëve, si era në guaskë. Dhe përhapej nëpër ujë, larg, shumë larg, mijëra kilometra.$s$,
    $s$Të gjitha krijesat e detit e njihnin këtë këngë. Kur e dëgjonin, e dinin që ishte koha e gjumit. Peshqit e vegjël me ngjyra mblidheshin mes koraleve. Breshkat e detit ngadalësonin notin dhe mbyllnin sytë. Oktapodët fshiheshin në shpellat e tyre dhe mbështillnin këmbët si lëmsh. Delfinët e vegjël flinin me një sy hapur, pranë nënave. Dhe kalit të detit, që flinte i lidhur pas barit me bisht, i dridhej buza nga kënaqësia.$s$,
    $s$Por një mbrëmje, ndodhi diçka e çuditshme. Bora u zhyt si gjithmonë, mori frymë dhe hapi gojën për të kënduar. Por nuk doli asnjë zë. Provoi përsëri. Vetëm flluska. Provoi për herë të tretë, dhe doli vetëm një fishkëllimë e hollë e e ngjirur. Bora e kishte humbur zërin.$s$,
    $s$Në të gjithë oqeanin, krijesat e detit pritën këngën. Peshqit e vegjël vazhduan të notonin, të hutuar. Breshkat s'po flinin dot. Delfinët e vegjël kërcenin mbi valë, sepse s'e dinin që ishte koha e gjumit. Oktapodi i vogël u ngatërrua në këmbët e tij. Dhe kali i vogël i detit filloi të qante, sepse pa ninullën, nuk kishte guxim të mbyllte sytë.$s$,
    $s$Bora u trishtua shumë. Notoi deri te gjyshja breshkë, që ishte njëqind e pesëdhjetë vjeç dhe dinte gjithçka për detin. «Më ka humbur zëri», i tha me fishkëllimën e saj të vogël. «Dhe pa ninullën time, askush s'po fle.» Gjyshja breshkë e dëgjoi me vëmendje. «Ke kënduar për të gjithë, çdo natë, për shumë vjet», tha. «Ndoshta është koha që dikush të këndojë për ty.»$s$,
    $s$Gjyshja breshkë notoi ngadalë, gjithnjë e më lart, deri te delfinët. U tregoi për Borën. Delfinët u tregonin peshqve. Peshqit u tregonin oktapodëve. Oktapodët u tregonin gaforreve. Dhe lajmi u përhap nëpër gjithë oqeanin, nga ujërat e ngrohta deri te akujt e veriut: Bora ka humbur zërin. Sonte, ne do të këndojmë për Borën.$s$,
    $s$Kur hëna u ngrit mbi det, ndodhi diçka që s'kishte ndodhur kurrë. Delfinët filluan të fishkëllenin një melodi të lehtë. Peshqit e vegjël përplasnin pendët, si duartrokitje të buta. Gaforret trokisnin me dorëzat mbi gurë, si daulle të vockla. Breshkat lëviznin ngadalë rrymën e ujit, si fryma e një ninulle. Dhe nga larg, nga ujërat e ftohta, erdhën balenat e tjera dhe filluan të këndonin me zërat e tyre të thella.$s$,
    $s$Ishte kënga më e çuditshme dhe më e bukur që kishte dëgjuar ndonjëherë deti. Nuk ishte e përsosur. Delfinët fishkëllenin pak shpejt, gaforret trokisnin pak me vonesë, dhe një peshk i vogël i verdhë këndonte gjithë kohën një notë tjetër. Por ishte kënduar me gjithë zemër, për Borën.$s$,
    $s$Bora e dëgjoi këngën duke notuar ngadalë në mes të oqeanit, me sytë që i ishin mbushur me lot. Lotët e balenave nuk duken në det, sepse përzihen me ujin e kripur. Por Bora i ndjeu. Ishin lot gëzimi. Gjithë jetën kishte kënduar për të tjerët, dhe tani të tjerët po këndonin për të. Dhe për herë të parë pas shumë kohësh, Bora mbylli sytë e saj të mëdhenj dhe e zuri gjumi, e lëkundur nga kënga e të gjithë detit.$s$,
    $s$Bora fjeti gjithë natën dhe gjithë ditën tjetër. Dhe kur u zgjua, në mbrëmjen e dytë, mori frymë thellë në sipërfaqe dhe provoi. Nga goja i doli një notë e thellë, e qartë e e bukur. Zëri i ishte kthyer! Sepse ndonjëherë, edhe zërat kanë nevojë të pushojnë.$s$,
    $s$Atë mbrëmje, Bora këndoi përsëri ninullën e saj. Por tani nuk këndonte vetëm. Delfinët fishkëllenin me të, peshqit përplasnin pendët, gaforret trokisnin, dhe peshku i vogël i verdhë këndonte, si gjithmonë, notën e tij të gabuar. Dhe kjo ishte, thonë, ninulla më e bukur e të gjithë oqeanit.$s$,
    $s$Sonte, nëse vë veshin mbi jastëk dhe dëgjon me shumë vëmendje, ndoshta do ta dëgjosh edhe ti, shumë larg, në mes të detit. Uuuuuu, këndon Bora. Fli, peshk i vogël. Fli, breshkë. Fli, kalë deti. Dhe fli edhe ti, fëmijë i vogël, në shtratin tënd të ngrohtë, si në një det të qetë.$s$
  ]::text[],
  array['sleep', 'nature']::text[], 0, 72, 10, 'boat',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gbalenaqekendonteninu" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#C6E3EC"/><stop offset="1" stop-color="#EEF7F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gbalenaqekendonteninu)"/><circle cx="34.8" cy="22" r="9" fill="#FFF3D6"/><path d="M40.7 34l4 3l4 -3M114.6 28l3 2.4l3 -2.4" fill="none" stroke="#5EA4B6" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><rect x="0" y="76" width="160" height="44" rx="0" fill="#8CC3CF"/><path d="M0 86Q10 82 20 86T40 86T60 86T80 86T100 86T120 86T140 86T160 86" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/><rect x="0" y="100" width="160" height="20" rx="0" fill="#5EA4B6"/><path d="M0 106Q10 102 20 106T40 106T60 106T80 106T100 106T120 106T140 106T160 106" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M4 40Q6 22 30 22Q50 22 54 36L60 30Q62 38 58 44Q62 50 60 54L54 46Q46 54 26 54Q6 54 4 40Z" fill="#2A5263"/><path d="M8 46Q28 50 50 44Q40 54 24 52Q12 51 8 46Z" fill="#EEF7F8" opacity="0.3"/><circle cx="16" cy="34" r="1.6" fill="#EEF7F8"/><path d="M24 18Q22 12 18 10M26 18Q28 12 32 10" fill="none" stroke="#E39A55" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M0 58Q12 55 24 58T48 58" fill="none" stroke="#E39A55" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
