(
  $s$bukuroshja-e-fjetur$s$, 'sq', $s$Bukuroshja e fjetur$s$,
  $s$Një princeshë dhe gjithë pallati i saj flenë njëqind vjet nën një gardh trëndafilash, deri sa vjen dikush me zemër të durueshme.$s$,
  array[
    $s$Na ishin një herë një mbret dhe një mbretëreshë që kishin dëshiruar shumë vite një fëmijë. Dhe një pranverë, më në fund, u lindi një vajzë e vogël, me faqe si trëndafila e me sy si qielli. E quajtën Aurora, që do të thotë agim, sepse u kishte sjellë dritë në zemër.$s$,
    $s$Për pagëzimin e saj, mbreti shtroi një gosti të madhe dhe ftoi të gjithë fisnikët dhe dymbëdhjetë zanat e mbretërisë, që t'i jepnin vajzës dhurata. Në mbretëri ishin trembëdhjetë zana, por mbreti kishte vetëm dymbëdhjetë pjata ari, dhe njërën nuk e ftoi.$s$,
    $s$Zanat iu afruan djepit njëra pas tjetrës. E para i dha mirësinë. E dyta, bukurinë. E treta, mençurinë. E katërta, një zë të bukur për të kënduar. E pesta, shëndet. Dhe kështu me radhë, deri te e njëmbëdhjeta. Por kur zana e dymbëdhjetë po afrohej, dyert u hapën me zhurmë dhe hyri zana e trembëdhjetë, e mërzitur dhe e fyer që s'ishte ftuar.$s$,
    $s$«Edhe unë kam një dhuratë», tha me zë të ftohtë. «Kur princesha të mbushë pesëmbëdhjetë vjeç, do t'i shpojë gishti me boshtin e një furke dhe do të bjerë përdhe.» Dhe doli nga salla pa e kthyer kokën. Mbretëresha filloi të qante. Por zana e dymbëdhjetë, që s'e kishte dhënë ende dhuratën, u afrua te djepi.$s$,
    $s$«Nuk mund ta zhbëj magjinë e saj», tha. «Por mund ta zbus. Princesha nuk do të bjerë përdhe për keq. Do të bjerë në një gjumë të thellë e të ëmbël, që do të zgjasë njëqind vjet. Dhe pastaj do të zgjohet.»$s$,
    $s$Mbreti urdhëroi që të digjeshin të gjitha furkat e mbretërisë. Aurora u rrit e mirë, e bukur dhe e mençur, ashtu si i kishin uruar zanat. Këndonte në kopshtin e pallatit dhe të gjithë që e njihnin e donin. Dhe me kalimin e viteve, të gjithë e harruan atë ditë pagëzimi.$s$,
    $s$Ditën kur mbushi pesëmbëdhjetë vjeç, Aurora po shëtiste vetëm nëpër pallat. Arriti te një kullë e vjetër, ku s'kishte qenë kurrë. U ngjit shkallëve të ngushta dhe dredha-dredha, dhe në majë gjeti një dhomë të vogël. Aty ishte ulur një plakë, që tirrte lesh me një furkë, ngadalë, ngadalë. «Ç'është kjo që rrotullohet kaq bukur?» pyeti Aurora, që s'kishte parë kurrë furkë.$s$,
    $s$«Eja ta provosh», tha plaka. Aurora zgjati dorën drejt boshtit, dhe sapo e preku, maja e tij i shpoi gishtin. Një pikë e vogël gjaku doli në gishtin e saj. Dhe në atë çast, Aurora ndjeu një lodhje të ëmbël, u shtri në shtratin e vogël të kullës dhe ra në një gjumë të thellë.$s$,
    $s$Dhe bashkë me të, ra në gjumë i gjithë pallati. Mbreti dhe mbretëresha, që sapo ishin kthyer, fjetën në fronet e tyre. Kuajt fjetën në ahur, qentë në oborr, pëllumbat në çati, mizat në mure. Kuzhinieri, që po përzinte supën, fjeti me lugën në dorë. Zjarri i vatrës pushoi së kërcituri dhe e zuri gjumi edhe atë. Edhe era pushoi, dhe asnjë gjethe nuk lëvizi më.$s$,
    $s$Rreth pallatit filloi të rritej një gardh me trëndafila të egër, që u bë çdo vit më i lartë e më i dendur, derisa e mbuloi të gjithin, deri në majën e kullës. Nga jashtë dukej vetëm një pyll me gjemba e me trëndafila të kuq. Dhe nëpër fshatra filloi të tregohej përralla e Bukuroshes së Fjetur, që flinte diku brenda.$s$,
    $s$Kaluan njëqind vjet. Një ditë, një princ nga një vend i largët dëgjoi nga një plak historinë e pallatit të fjetur. «Shumë kanë provuar të kalojnë gardhin», i tha plaku, «por gjembat nuk i lënë.» Princi nuk u tremb. Ishte i durueshëm dhe i butë, dhe kishte dëgjuar se edhe gjërat më të vështira hapen me kohën e duhur.$s$,
    $s$Kur princi u afrua, njëqind vjetët sapo kishin mbaruar. Dhe gardhi me gjemba, para syve të tij, u mbulua papritur me trëndafila të mëdhenj e të butë, që u hapën vetë dhe i lanë një shteg. Princi eci nëpër oborrin ku flinin qentë, nëpër kuzhinën ku flinte kuzhinieri, nëpër sallën ku flinin mbreti e mbretëresha, dhe u ngjit në kullë. Aty pa Aurorën, që flinte e qetë, sikur të kishte mbyllur sytë një minutë më parë.$s$,
    $s$Princi u ul në gjunjë pranë saj dhe i dha një puthje të lehtë në ballë. Aurora hapi sytë dhe i buzëqeshi, sikur ta njihte. Dhe në atë çast u zgjua gjithë pallati. Mbreti dhe mbretëresha u ngritën nga fronet. Kuajt hingëllinë, qentë lehën, pëllumbat fluturuan. Zjarri u ndez përsëri, dhe kuzhinieri vazhdoi të përzinte supën, sikur të mos kishte ndodhur asgjë.$s$,
    $s$Pas pak ditësh, Aurora dhe princi u martuan, në një dasmë ku u ftuan të trembëdhjetë zanat. Këtë herë mbreti kishte bërë gati trembëdhjetë pjata ari, sepse kishte mësuar se askush nuk duhet lënë jashtë. Dhe Aurora, që kishte fjetur njëqind vjet, thoshte gjithmonë me shaka se tani s'kishte më nevojë të flinte kurrë. Por çdo mbrëmje, flinte e qetë, si gjithë ne. Natën e mirë.$s$
  ]::text[],
  array['classic', 'sleep']::text[], 48, 120, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gbukuroshjaefjetur" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E3A08A"/><stop offset="1" stop-color="#F6D6BD"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gbukuroshjaefjetur)"/><circle cx="28.2" cy="80" r="22" fill="#FFF1DE" opacity="0.8"/><path d="M38 30l4 3l4 -3M118.4 24l3 2.4l3 -2.4" fill="none" stroke="#B47266" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><path d="M0 87.7Q40 69.4 80 81.4T160 82.4V120H0Z" fill="#D2917E"/><path d="M0 99.3Q40 89.8 80 97.8T160 103.3V120H0Z" fill="#B47266"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><rect x="6" y="22" width="12" height="38" rx="0" fill="#FFF5E8"/><rect x="46" y="22" width="12" height="38" rx="0" fill="#FFF5E8"/><rect x="18" y="32" width="28" height="28" rx="0" fill="#FFF5E8"/><path d="M4 22L12 8L20 22Z" fill="#7A3E3A"/><path d="M44 22L52 8L60 22Z" fill="#7A3E3A"/><path d="M12 8V0M52 8V0" fill="none" stroke="#FFF5E8" stroke-width="1" stroke-linecap="round" stroke-linejoin="round"/><path d="M12 0L18 2L12 4Z" fill="#7A3E3A"/><path d="M52 0L58 2L52 4Z" fill="#7A3E3A"/><path d="M26 60V48Q32 42 38 48V60Z" fill="#C98673"/><rect x="9" y="30" width="4" height="6" rx="2" fill="#C98673"/><rect x="49" y="30" width="4" height="6" rx="2" fill="#C98673"/><rect x="20" y="28" width="4" height="4" rx="0" fill="#FFF5E8"/><rect x="26" y="28" width="4" height="4" rx="0" fill="#FFF5E8"/><rect x="32" y="28" width="4" height="4" rx="0" fill="#FFF5E8"/><rect x="38" y="28" width="4" height="4" rx="0" fill="#FFF5E8"/></g></svg>$s$,
  'published', false, 300, 'editor'
),
(
  $s$rosaku-i-shemtuar$s$, 'sq', $s$Rosaku i shëmtuar$s$,
  $s$Sipas Hans Kristian Andersenit: një zog gri e i ngathët, që të gjithë e quajnë të shëmtuar, kalon një dimër të gjatë derisa zbulon se kush është vërtet.$s$,
  array[
    $s$Ishte verë në fshat dhe gjithçka ishte e bukur. Gruri ishte i verdhë, bari ishte i gjelbër, dhe lejlekët ecnin me këmbët e tyre të gjata të kuqe nëpër livadh. Pranë një pellgu, mes gjetheve të mëdha të rodhes, një rosë po ngrohte vezët e saj dhe priste me padurim që të çeleshin.$s$,
    $s$Më në fund, kric-krac, vezët u çanë njëra pas tjetrës, dhe dolën rosakë të vegjël të verdhë, që thërrisnin «pip, pip» dhe shikonin botën me habi. Por mbeti një vezë, më e madhe se të tjerat. Rosa u ul përsëri mbi të dhe priti. Kur më në fund u ça, prej saj doli një zog i madh, gri e i ngathët, krejt ndryshe nga vëllezërit e tij.$s$,
    $s$«Sa i çuditshëm është», tha rosa. «Por noton mirë dhe e mban qafën drejt. Është i imi.» Dhe e mori me vete në oborrin e fermës. Por aty, të gjithë qeshnin me të. Rosat e tjera e shtynin, pulat e çukitnin, dhe gjeli i madh fryhej si balonë sa herë që e shihte. «Sa i shëmtuar!» thoshin. Edhe vëllezërit e tij e thërrisnin «rosaku i shëmtuar».$s$,
    $s$Rosaku i gjorë nuk dinte ku të fshihej. Çdo ditë bëhej më keq, deri sa një mëngjes, kaloi mbi gardh dhe iku. Fluturoi sa mundi, me krahët e tij ende të dobët, derisa arriti në një moçal të madh, ku jetonin rosat e egra. «Je shumë i shëmtuar», i thanë edhe ato, «por nuk ka rëndësi, mjafton të mos martohesh me ndonjërën nga tonat.» Rosaku ishte aq i trishtuar, sa as nuk u përgjigj.$s$,
    $s$Eci shumë ditë. Arriti te një kasolle e vogël, ku jetonte një plakë me një mace dhe një pulë. Plaka nuk shihte mirë dhe e mori për rosë që bën vezë. Por maca dhe pula ishin mendjemëdha. «A di të bësh vezë?» e pyeste pula. «Jo.» «A di të kërrusësh shpinën e të bësh mrrr?» e pyeste maca. «Jo.» «Atëherë, s'je i mirë për asgjë», i thoshin. Rosaku mendonte vetëm për ujin, për notin, për valët që e lëkundnin, dhe një ditë iku edhe prej andej.$s$,
    $s$Erdhi vjeshta. Gjethet u bënë të verdha e të kuqe, dhe era i hidhte nëpër ajër. Një mbrëmje, ndërsa dielli perëndonte, rosaku pa një tufë zogjsh të mrekullueshëm që fluturonin lart në qiell. Ishin të bardhë, të shkëlqyer, me qafa të gjata e të hijshme. Ishin mjellma. Po fluturonin drejt vendeve të ngrohta. Rosaku i ndoqi me sy deri sa u zhdukën, dhe zemra i rrihte fort. Nuk e dinte pse, por i donte, siç s'kishte dashur kurrë asgjë.$s$,
    $s$Pastaj erdhi dimri, i gjatë e i ftohtë. Pellgu ku jetonte rosaku filloi të ngrinte, dhe ai duhej të notonte pa pushim që uji të mos mbyllej rreth tij. Por një natë, u lodh aq shumë sa ndaloi, dhe akulli e zuri. Në mëngjes, një fshatar e pa, e çau akullin me këpucën e tij të drunjtë dhe e çoi në shtëpi, që ta ngrohte pranë zjarrit.$s$,
    $s$Fëmijët e fshatarit donin të luanin me të, por rosaku u tremb, se mendonte që do t'i bënin keq. U përplas në enën e qumështit dhe në thesin e miellit, dhe doli me vrap nga dera. Kaloi pjesën tjetër të dimrit në kallamat e një liqeni, i vetmuar e i ngrirë. Mos më pyet sa i vështirë ishte ai dimër. Mjafton të të them që kaloi.$s$,
    $s$Pastaj, një ditë, dielli filloi të ngrohte përsëri. Zogjtë filluan të këndonin. Ishte pranverë. Rosaku i shëmtuar hapi krahët dhe vuri re se ishin bërë më të fortë. Ngriti fluturimin, dhe para se ta kuptonte, ishte në një kopsht të madh, ku pemët e mollës kishin çelur dhe degët e shelgjeve vareshin mbi ujin e një kanali.$s$,
    $s$Aty, nga pas kallamave, dolën tri mjellma të bardha, që notonin lehtë mbi ujë, me pendët e fryra. Rosaku i njohu. Ishin zogjtë e mrekullueshëm të vjeshtës. «Do të shkoj tek ato», tha me vete. «Ndoshta do të më përzënë, sepse jam kaq i shëmtuar. Por më mirë të më përzënë ato, se sa të më çukitin pulat e të më përqeshë gjithë bota.» Dhe notoi drejt tyre, me kokën ulur, duke pritur më të keqen.$s$,
    $s$Por ndërsa ulte kokën, pa diçka në ujin e kthjellët: pasqyrimin e vet. Nuk ishte më një zog gri, i ngathët e i shëmtuar. Ishte një mjellmë. Një mjellmë e bardhë, me qafë të gjatë e të hijshme. Rosaku i shëmtuar s'kishte qenë kurrë rosak. Kishte qenë gjithmonë një mjellmë, që thjesht kishte lindur në folenë e një rose.$s$,
    $s$Mjellmat e tjera notuan rreth tij dhe e përkëdhelën me sqepat e tyre, si të ishte vëlla i tyre që sapo ishte kthyer. Pranë kanalit erdhën disa fëmijë, që hidhnin bukë në ujë. «Shikoni!» thirri më i vogli. «Ka ardhur një mjellmë e re! Dhe është më e bukura nga të gjitha!»$s$,
    $s$Mjellma e re ndjeu një turp të ëmbël dhe e fshehu kokën nën krah. Nuk ishte krenare, sepse një zemër e mirë nuk bëhet kurrë krenare. Kujtonte gjithë ditët kur e kishin përbuzur dhe kur kishte qenë vetëm. Por tani e dinte. Hapi krahët, ngriti qafën e gjatë dhe tha me gjithë zemër: «Nuk e kisha ëndërruar kurrë këtë lumturi, kur isha rosaku i shëmtuar.»$s$,
    $s$Dhe nëse ndonjëherë ndihesh si rosaku i vogël gri në oborrin e fermës, kujto këtë përrallë. Ndoshta ende s'e ke parë veten në ujin e kthjellët. Por do të vijë pranvera.$s$
  ]::text[],
  array['classic', 'emotions']::text[], 36, 96, 12, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="grosakuishemtuar" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#C6E3EC"/><stop offset="1" stop-color="#EEF7F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#grosakuishemtuar)"/><circle cx="29.8" cy="22" r="9" fill="#FFF3D6"/><path d="M40 34l4 3l4 -3M117 28l3 2.4l3 -2.4" fill="none" stroke="#5EA4B6" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><rect x="0" y="76" width="160" height="44" rx="0" fill="#8CC3CF"/><path d="M0 86Q10 82 20 86T40 86T60 86T80 86T100 86T120 86T140 86T160 86" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/><rect x="0" y="100" width="160" height="20" rx="0" fill="#5EA4B6"/><path d="M0 106Q10 102 20 106T40 106T60 106T80 106T100 106T120 106T140 106T160 106" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M6 44Q8 33 25 33L39 35Q45 35 43 29Q39 21 41 13Q43 7 49 9L55 13L49 14Q45 16 47 24Q53 40 39 48Q19 52 6 44Z" fill="#2A5263"/><path d="M54 12L60 15L54 15.5Z" fill="#E39A55"/><circle cx="48.5" cy="11.5" r="1" fill="#EEF7F8"/><path d="M16 38Q26 34 34 39Q24 43 16 38Z" fill="#EEF7F8" opacity="0.25"/><path d="M2 54Q14 51 26 54T52 54" fill="none" stroke="#EEF7F8" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/></g></svg>$s$,
  'published', false, 310, 'editor'
),
(
  $s$ku-flene-kafshet$s$, 'sq', $s$Ku flenë kafshët?$s$,
  $s$Para gjumit, Noli pyet babanë ku flenë kafshët. Babai i tregon: kali në këmbë, lakuriqi i natës kokëposhtë, vidrat duke u mbajtur për dore dhe flamingoja mbi një këmbë.$s$,
  array[
    $s$«Babi», pyeti Noli, kur babai po i rregullonte jorganin, «unë fle në shtrat. Ti dhe mami flini në shtratin e madh. Po kafshët? Ku flenë kafshët?» Babai u ul në buzë të shtratit dhe buzëqeshi. «Pyetje e mirë», tha. «Le të shkojmë t'i vizitojmë, me mend, pa u ngritur nga shtrati. Mbyll sytë.»$s$,
    $s$«Së pari», tha babai, «shkojmë në fermë. Shikon kalin? Është në ahur, nën dritën e hënës që hyn nga dritarja. Dhe e di si fle? Në këmbë! Kali mund të flejë në këmbë, sepse këmbët e tij kanë një kyç të veçantë që nuk e lë të bjerë. Kështu, nëse vjen ndonjë rrezik, ai është gati të vrapojë. Por kur ndihet shumë i sigurt, shtrihet në kashtë, si ti.»$s$,
    $s$«Pranë kalit», vazhdoi babai, «në kotec, flenë pulat. Ato ngjiten mbi një shkop druri, sa më lart, dhe flenë të gjitha në rresht, ngjitur njëra me tjetrën. Gjeli fle në fund të rreshtit, që të jetë i pari që sheh diellin në mëngjes dhe ta zgjojë fermën.»$s$,
    $s$«Tani fluturojmë në pyll», tha babai, dhe Noli imagjinoi që po fluturonte mbi pemë. «Shikon atë shpellën? Brenda, të varur nga tavani, ka shumë lakuriqë nate. Flenë kokëposhtë, të mbështjellë në krahët e tyre si në një batanije. Por kujdes, mos u bëj zhurmë, se ata flenë ditën, dhe tani, natën, po zgjohen për të kërkuar mushkonja.»$s$,
    $s$«Në degën e atij lisi», tha babai me zë të ulët, «sheh dy sy të verdhë? Është bufi. Edhe ai rri zgjuar natën. Po në mëngjes, kur të zgjohesh ti, bufi do të mbyllë sytë dhe do të flejë gjithë ditën, i fshehur mes gjetheve. Ndryshe nga ti, bufi i thotë diellit natën e mirë.»$s$,
    $s$«Poshtë lisit, nën gjethet e thata, është një iriq i vogël. Ai fle gjatë, shumë gjatë. Gjithë dimrin! Mbështillet si top, me gjembat nga jashtë, në një fole prej gjethesh, dhe fle nga nëntori deri në mars. Kjo quhet gjumë dimëror. Edhe ariu e bën, në shpellën e tij. Imagjino të flesh kaq gjatë! Do të të duhej një jorgan shumë i trashë.»$s$,
    $s$«Tani shkojmë buzë detit», tha babai. «Shikon ato dy kafshë të vogla që notojnë në shpinë, mbi valë? Janë vidra deti. Kur flenë në ujë, e mbajnë njëra-tjetrën për dore, që rryma të mos i ndajë. Dhe kur deti ka rryma, mbështillen me bar deti, si me një rrip sigurimi.» Noli buzëqeshi me sytë mbyllur. «Si unë dhe ti, kur kalojmë rrugën», tha.$s$,
    $s$«Pikërisht», tha babai. «Tani shkojmë pak më larg, te liqeni i madh. Ata zogjtë rozë, me këmbë të gjata e të holla, janë flamingo. Dhe flenë mbi një këmbë të vetme! Tjetrën e mbledhin nën pupla, që të mos u ftohet. Dhe e fusin kokën nën krah. Duken si një lule rozë mbi një bisht të hollë.»$s$,
    $s$«Dhe në det?» pyeti Noli, me zë gjithnjë e më të përgjumur. «Në det», tha babai, «delfinët flenë me gjysmën e trurit. Njëri sy fle, tjetri rri hapur. Kështu mund të notojnë, të marrin frymë e të ruhen, edhe duke fjetur. Dhe disa balena flenë në këmbë, edhe pse s'kanë këmbë fare! Rrinë drejt në ujë, si trungje të mëdha që notojnë, me kokën lart.»$s$,
    $s$«Dhe gjirafa?» pëshpëriti Noli. «Gjirafa fle shumë pak», tha babai, «vetëm disa minuta në të njëjtën kohë, ndonjëherë në këmbë. Por kur fle e shtrirë, e përdredh qafën e gjatë dhe e vë kokën mbi shpinën e saj, si mbi një jastëk. Dhe këlyshët e saj flenë të shtrirë pranë nënës, me qafat e gjata në bar.»$s$,
    $s$«Po macja jonë?» Noli kishte sytë mbyllur tani. «Macja jonë», tha babai, «po fle pikërisht tani te këmbët e tua, mbi jorgan. Macet flenë shumë, gati gjysmën e ditës. Dhe kur flenë, ëndërrojnë. Ndoshta po ëndërron për minj, ose për lëmshe leshi. Shiko si i dridhen mustaqet.»$s$,
    $s$Noli nuk u përgjigj. Babai shikoi dhe pa që sytë i ishin mbyllur krejt dhe frymëmarrja i ishte bërë e ngadaltë e e qetë. Kishte fjetur, në mes të kafshëve: kali në ahur, pulat në shkop, lakuriqët kokëposhtë, iriqi në gjethe, vidrat dorë për dore, flamingoja mbi një këmbë, delfini me një sy hapur, gjirafa me kokën në shpinë.$s$,
    $s$Babai u ngrit ngadalë, e përkëdheli macen dhe fiku dritën. «Natën e mirë, Nol», pëshpëriti. «Dhe ti, ku fle? Ti fle në shtratin tënd të ngrohtë, nën jorgan, në shtëpinë tënde, me mamin dhe babin në dhomën ngjitur. Vendi më i sigurt nga të gjithë.» Natën e mirë, kafshë të botës. Natën e mirë, ti.$s$
  ]::text[],
  array['sleep', 'nature']::text[], 0, 72, 10, 'owl',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkuflenekafshet" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkuflenekafshet)"/><path d="M105 13.200000000000001Q105 16.8 108.6 16.8Q105 16.8 105 20.400000000000002Q105 16.8 101.4 16.8Q105 16.8 105 13.200000000000001Z" fill="#F3EBD9" opacity="0.9"/><circle cx="18" cy="32.7" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="132.1" cy="34.2" r="0.9" fill="#F3EBD9" opacity="0.7"/><path d="M20 19.5Q20 22.1 22.6 22.1Q20 22.1 20 24.700000000000003Q20 22.1 17.4 22.1Q20 22.1 20 19.5Z" fill="#F3EBD9" opacity="0.9"/><circle cx="126.4" cy="27.2" r="1.3" fill="#F3EBD9" opacity="0.7"/><path d="M150.3 33.699999999999996Q150.3 36.3 152.9 36.3Q150.3 36.3 150.3 38.9Q150.3 36.3 147.70000000000002 36.3Q150.3 36.3 150.3 33.699999999999996Z" fill="#F3EBD9" opacity="0.9"/><circle cx="11" cy="9.7" r="1.3" fill="#F3EBD9" opacity="0.7"/><circle cx="89.6" cy="8.4" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="35.2" cy="22" r="11" fill="#F3EBD9"/><circle cx="41.2" cy="18" r="10" fill="#1E3446"/><path d="M0 92.2Q40 83 80 93T160 86.1V120H0Z" fill="#24455A"/><path d="M0 101.3Q40 95 80 103T160 97.8V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M2 58L62 58" fill="none" stroke="#8A5A44" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="32" cy="36" rx="16" ry="20" fill="#F3EBD9"/><path d="M17 22L20 10L27 18Z" fill="#F3EBD9"/><path d="M47 22L44 10L37 18Z" fill="#F3EBD9"/><circle cx="25" cy="30" r="6.5" fill="#24455A"/><circle cx="39" cy="30" r="6.5" fill="#24455A"/><circle cx="25" cy="30" r="2.8" fill="#F3EBD9"/><circle cx="39" cy="30" r="2.8" fill="#F3EBD9"/><path d="M30 36L32 41L34 36Z" fill="#E7B04B"/><path d="M22 44Q32 50 42 44" fill="#