(
  $s$bilbil-gjizari$s$, 'sq', $s$Bilbil Gjizari$s$,
  $s$Përrallë popullore shqiptare: tre vëllezër kërkojnë zogun që këndon aq bukur sa shëron trishtimin. E gjen ai që di të ndihmojë dhe të mbajë fjalën.$s$,
  array[
    $s$Na ishte një herë një mbret i plakur, që kishte tre djem. Një dimër, mbretit i ra një trishtim i rëndë. Nuk hante, nuk qeshte dhe rrinte gjithë ditën te dritarja, duke parë kopshtin pa lule. Mjekët e oborrit provuan çaj, barëra dhe këngë, por asgjë nuk e ndihmonte.$s$,
    $s$Një natë, një shërbëtore e vjetër u tha djemve: «Kam dëgjuar nga gjyshja ime për një zog që quhet Bilbil Gjizari. Kush e dëgjon të këndojë, e harron çdo trishtim. Thonë se jeton në kopshtin e të Bukurës së Dheut, përtej shtatë maleve.»$s$,
    $s$Djali i madh u nis i pari, me kalin më të shpejtë. Pas tij u nis i mesmi, me shpatën më të bukur. I fundit u nis djali i vogël, që s'kishte as kalë të shpejtë, as shpatë të bukur, por kishte një trastë me bukë dhe një zemër të butë.$s$,
    $s$Në një udhëkryq, te rrënjët e një lisi të vjetër, rrinte ulur një plakë me një deng dru përpara. «Biri im», i tha djalit të madh, «më ndihmo t'i çoj këto dru deri në shtëpi.» «S'kam kohë, plakë», tha ai dhe kaloi me galop. Të njëjtën gjë i tha edhe i mesmi, pa e kthyer as kokën.$s$,
    $s$Kur erdhi djali i vogël, plaka i kërkoi të njëjtën gjë. Ai zbriti, e ngarkoi dengun në shpinë dhe ia çoi deri te kasolla e saj. Pastaj i dha gjysmën e bukës që kishte në trastë. Plaka e vështroi me sy që shkëlqenin si dy yje. «Ti po kërkon Bilbil Gjizarin», i tha. «Dëgjo me kujdes, se do të të tregoj si ta gjesh.»$s$,
    $s$«Kopshti i të Bukurës së Dheut ruhet nga dy luanë prej guri, që flenë vetëm në mesditë. Hyr atëherë, me hapa të lehtë. Bilbili rri në një kafaz të artë mbi një shegë. Mos e prek kafazin, se do të bjerë zile. Mos fol me zë të lartë. Dhe nëse bilbili të flet, dëgjoje.»$s$,
    $s$Djali i vogël eci shtatë ditë e shtatë net. Kaloi male me borë, lumenj të ftohtë dhe fusha pa fund. Në mëngjesin e tetë, pa një mur të gjatë të mbuluar me trëndafila. Pranë portës rrinin dy luanë prej guri. Ai u ul në hije dhe priti. Kur dielli u ngjit në mes të qiellit, luanët mbyllën sytë dhe nisën të gërhitnin ngadalë.$s$,
    $s$Djali hyri në kopsht. Kishte pemë me fruta që shkëlqenin si fenerë dhe lule që ndryshonin ngjyrë sa herë që i shikoje. Në mes ishte një shegë e madhe, dhe në degën e saj, një kafaz i artë. Brenda tij rrinte një zog i vogël kafe, aq i thjeshtë sa s'do ta kishe vënë re. Ky ishte Bilbil Gjizari.$s$,
    $s$Bilbili e pa dhe i foli me zë të ulët: «E di pse ke ardhur. Por unë jam lodhur duke kënduar brenda një kafazi. Një këngë e mbyllur s'është më këngë. Nëse më premton se s'do të më mbyllësh kurrë, do të vij me ty me dëshirën time dhe do t'i këndoj babait tënd.»$s$,
    $s$«Të premtoj», tha djali. Nuk e preku kafazin. Hapi vetëm derën e vogël, me një gisht, aq lehtë sa zilja s'ra fare. Bilbili doli, iu ul në sup dhe të dy u larguan nga kopshti, ndërsa luanët prej guri gërhitnin ende në diell.$s$,
    $s$Në rrugë të kthimit, djali i gjeti vëllezërit e tij të ulur pranë një burimi, të lodhur e me duar bosh. I madhi kishte humbur kalin, i mesmi shpatën. Djali i vogël nuk i qortoi. U dha bukë nga trasta e tij, dhe të tre u kthyen bashkë në shtëpi.$s$,
    $s$Kur arritën në pallat, bilbili fluturoi te dritarja e mbretit dhe nisi të këndonte. Kënga e tij ishte si uji i burimit, si era në gjethe, si zëri i nënës që të zgjon në mëngjes. Mbreti ngriti kokën. Pastaj buzëqeshi. Pastaj qeshi me zë, siç s'kishte qeshur prej shumë kohësh. Dhe atë ditë, për herë të parë pas gjithë atij dimri, kërkoi të hante.$s$,
    $s$Bilbil Gjizari nuk u fut kurrë në kafaz. Jetonte i lirë në kopshtin e pallatit dhe çdo mëngjes këndonte te dritarja e mbretit. Kopshti u mbush përsëri me lule. Dhe kur mbreti u plak shumë, ia la fronin djalit të vogël, sepse tha: «Kush di të ndihmojë një plakë dhe të mbajë fjalën që i jep një zogu, di edhe të kujdeset për një vend të tërë.»$s$,
    $s$Thonë se Bilbil Gjizari këndon ende, diku, në kopshtet ku njerëzit nuk i mbyllin zogjtë. Ndoshta, nëse dëgjon me vëmendje në agim, do ta dëgjosh edhe ti.$s$
  ]::text[],
  array['classic', 'adventure']::text[], 48, 120, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gbilbilgjizari" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F2C8B6"/><stop offset="1" stop-color="#FBE9DA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gbilbilgjizari)"/><circle cx="35.5" cy="86" r="22" fill="#FFF1DE" opacity="0.8"/><path d="M41.8 30l4 3l4 -3M127.7 24l3 2.4l3 -2.4" fill="none" stroke="#CB9582" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><path d="M0 87.5Q40 78.6 80 90.6T160 80V120H0Z" fill="#E2AF9B"/><path d="M0 102.7Q40 88.4 80 96.4T160 99.1V120H0Z" fill="#CB9582"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M4 52Q32 46 62 50" fill="none" stroke="#8A5A44" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="56" cy="46" rx="4" ry="2" fill="#7DA86B" transform="rotate(-20 56 46)"/><path d="M20 40L4 44L9 36Z" fill="#5A4560"/><ellipse cx="30" cy="38" rx="14" ry="10" fill="#5A4560" transform="rotate(-12 30 38)"/><circle cx="42" cy="30" r="7" fill="#5A4560"/><path d="M48 29L55 30.5L48 32Z" fill="#E07B5F"/><path d="M24 36Q32 32 38 38Q30 42 24 36Z" fill="#F8DDCC" opacity="0.35"/><circle cx="44" cy="28.5" r="1.4" fill="#F8DDCC"/><path d="M30 47L29 51M34 47L34 51" fill="none" stroke="#E07B5F" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 330, 'editor'
),
(
  $s$princesha-dhe-bizelja$s$, 'sq', $s$Princesha dhe bizelja$s$,
  $s$Sipas Hans Kristian Andersenit: një princ kërkon një princeshë të vërtetë, dhe mbretëresha ka një provë të çuditshme me një kokërr bizele nën njëzet dyshekë.$s$,
  array[
    $s$Na ishte një herë një princ që donte të martohej me një princeshë. Por jo me një princeshë çfarëdo: ai donte një princeshë të vërtetë. Prandaj udhëtoi nëpër gjithë botën për të gjetur një të tillë.$s$,
    $s$Takoi shumë princesha. Disa kishin kurora të mëdha prej ari, por s'qeshnin kurrë. Disa dinin të kërcenin bukur, por s'dëgjonin askënd. Njëra fliste vetëm për fustanet e saj, tjetra fliste vetëm për kuajt e saj. Dhe princi kthehej gjithmonë me ndjesinë se diçka nuk shkonte. «Si mund ta dish nëse dikush është vërtet princeshë?» i tha nënës së tij, mbretëreshës. Mbretëresha nuk u përgjigj. Vetëm buzëqeshi, si dikush që ka një ide.$s$,
    $s$Një mbrëmje, shpërtheu një stuhi e tmerrshme. Vetëtimat çanin qiellin, bubullimat tundnin dritaret, dhe shiu binte aq i dendur sa dukej sikur qielli ishte kthyer përmbys. Në mes të stuhisë, dikush trokiti në portën e pallatit. Mbreti i vjetër shkoi vetë ta hapte.$s$,
    $s$Para portës qëndronte një vajzë. Por çfarë pamjeje kishte nga shiu e nga era! Uji i kullonte nga flokët e nga rrobat, i hynte nga majat e këpucëve dhe i dilte nga thembrat. Dhe megjithatë, ajo tha me zë të qetë se ishte një princeshë e vërtetë, që kishte humbur rrugën në stuhi.$s$,
    $s$«Do ta shohim», mendoi mbretëresha, por nuk tha asgjë. E ftoi vajzën brenda, i dha rroba të thata, e uli pranë zjarrit dhe i dha supë të nxehtë. Princi u ul përballë saj. Ajo i tregoi për vendin e saj të largët, për librat që lexonte, për kopshtin ku mbillte lule me duart e veta. Dhe kur princi tregoi një shaka të keqe, ajo qeshi me gjithë zemër, pastaj i tha me mirësjellje që shakaja nuk ishte shumë e mirë. Princit i pëlqeu shumë ky sinqeritet.$s$,
    $s$Ndërkohë, mbretëresha shkoi në dhomën e miqve. Hoqi të gjitha shtrojet nga shtrati dhe vuri në fund të tij një kokërr të vogël bizele, të gjelbër e të rrumbullakët. Pastaj, mbi bizelen, vuri njëzet dyshekë, njërin mbi tjetrin. Dhe mbi njëzet dyshekët, vuri njëzet jorganë me pupla pate. Shtrati u bë aq i lartë, sa vajzës iu desh një shkallë për t'u ngjitur.$s$,
    $s$«Natën e mirë», i tha mbretëresha, «dhe fli rehat.» Vajza u ngjit shkallëve, deri në majën e shtratit, u shtri dhe fiku qiririn. Jashtë, stuhia vazhdonte të gjëmonte, por në pallat gjithçka ishte e qetë.$s$,
    $s$Në mëngjes, mbretëresha e pyeti: «Si fjete, bija ime?» Vajza psherëtiu, e lodhur. «Oh, shumë keq! Nuk mbylla sy gjithë natën. Nuk e di çfarë kishte në atë shtrat, por isha shtrirë mbi diçka të fortë, dhe tani jam e mbuluar me njolla blu. Më falni që ua them, sepse shtrati ishte shumë i bukur. Por s'dua t'ju gënjej.»$s$,
    $s$Mbretëresha buzëqeshi, sepse tani e dinte. Vetëm një princeshë e vërtetë mund ta ndjente një kokërr bizele përmes njëzet dyshekëve dhe njëzet jorganëve me pupla. Askush tjetër s'mund të kishte një lëkurë kaq të ndjeshme.$s$,
    $s$Por princi e dinte diçka edhe më të rëndësishme. «Nëna ime ka provën e saj», tha me vete, «por unë kam timen. Ajo vajzë më tha të vërtetën për shakanë time të keqe, dhe të vërtetën për shtratin e nënës sime, edhe pse do të ishte më e lehtë të gënjente. Kjo është një princeshë e vërtetë.»$s$,
    $s$Princi i kërkoi dorën, dhe vajza pranoi, sepse edhe asaj i kishte pëlqyer princi, me shakatë e tij të këqija e me zemrën e tij të mirë. U martuan pas pak ditësh, në një dasmë ku dielli shkëlqeu gjithë ditën, sikur stuhia të mos kishte qenë kurrë.$s$,
    $s$Dhe kokrra e bizeles? E vendosën në muzeun e pallatit, në një kuti xhami mbi një jastëk të kuq kadifeje, me një shënim të vogël: «Bizelja që gjeti një princeshë.» Dhe nëse askush s'e ka marrë, është ende aty.$s$,
    $s$Kjo është një përrallë e vërtetë. Ose të paktën, aq e vërtetë sa çdo përrallë e mirë. Dhe sonte, kur të shtrihesh në shtratin tënd, kontrollo mirë: mos ka ndonjë bizele poshtë dyshekut? Jo? Atëherë do të flesh shumë mirë. Natën e mirë, princ i vogël. Natën e mirë, princeshë e vogël.$s$
  ]::text[],
  array['classic', 'sleep']::text[], 36, 96, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gprinceshadhebizelja" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gprinceshadhebizelja)"/><path d="M132.9 16.2Q132.9 19.9 136.6 19.9Q132.9 19.9 132.9 23.599999999999998Q132.9 19.9 129.20000000000002 19.9Q132.9 19.9 132.9 16.2Z" fill="#F3EBD9" opacity="0.9"/><circle cx="49" cy="42.1" r="1.6" fill="#F3EBD9" opacity="0.7"/><circle cx="140.1" cy="9.8" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="18.8" cy="35.8" r="1" fill="#F3EBD9" opacity="0.7"/><path d="M71.9 8.2Q71.9 10.4 74.10000000000001 10.4Q71.9 10.4 71.9 12.600000000000001Q71.9 10.4 69.7 10.4Q71.9 10.4 71.9 8.2Z" fill="#F3EBD9" opacity="0.9"/><circle cx="39.7" cy="8.9" r="1.5" fill="#F3EBD9" opacity="0.7"/><circle cx="30.1" cy="22" r="11" fill="#F3EBD9"/><circle cx="36.1" cy="18" r="10" fill="#1E3446"/><path d="M0 91.8Q40 76.1 80 86.1T160 90.8V120H0Z" fill="#24455A"/><path d="M0 102.3Q40 92.6 80 100.6T160 97.5V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><rect x="8" y="50" width="48" height="6" rx="3" fill="#E58C8A"/><rect x="8" y="44" width="48" height="6" rx="3" fill="#7FB8C6"/><rect x="8" y="38" width="48" height="6" rx="3" fill="#E7B04B"/><rect x="8" y="32" width="48" height="6" rx="3" fill="#A6CDB4"/><rect x="8" y="26" width="48" height="6" rx="3" fill="#C9A0D6"/><rect x="8" y="20" width="48" height="6" rx="3" fill="#F4D7BE"/><circle cx="18" cy="59" r="2.5" fill="#7DA86B"/><path d="M18 14Q24 6 32 10Q40 6 46 14Z" fill="#F3EBD9"/></g></svg>$s$,
