(
  $s$batanija-me-arna$s$, 'sq', $s$Batanija me arna e gjyshes$s$,
  $s$Batanija e Anës është bërë me copa nga rrobat e vjetra të familjes. Çdo mbrëmje, gjyshja i tregon historinë e një arne, derisa Anën e zë gjumi.$s$,
  array[
    $s$Ana kishte një batanije të veçantë. Nuk ishte e blerë në dyqan. E kishte qepur gjyshja me duart e saj, gjatë një dimri të tërë, me copa pëlhure nga rrobat e vjetra të familjes. Kishte arna të kuqe, blu, të verdha, me lule, me kuadrate, me vija e me pika. Dhe çdo arnë kishte një histori.$s$,
    $s$Çdo mbrëmje, para gjumit, gjyshja ulej pranë shtratit të Anës, me syzet në majë të hundës, dhe Ana zgjidhte një arnë me gisht. «Kjo», thoshte. Dhe gjyshja tregonte historinë e saj. Atë mbrëmje, Ana zgjodhi një arnë blu të çelët, me yje të vegjël të bardhë.$s$,
    $s$«Ah, kjo», tha gjyshja, dhe sytë iu ndriçuan. «Kjo është nga pizhamat e tua të para. Kur linde, ishe aq e vogël, sa të futnim në pizhama të një kukulle. Dhe kur t'i vishnim këto me yje, babai yt të këndonte: Ylli im i vogël, ylli im i vogël. Ti e kapje gishtin e tij me dorën e vockël dhe s'ia lëshoje gjithë natën.» Ana e preku arnën. Ishte e butë, shumë e butë, si një frymë.$s$,
    $s$«Dhe kjo?» Ana tregoi një arnë të kuqe, me pika të bardha. «Kjo është nga fustani që mamaja jote mbante ditën kur u njoh me babanë tënd», tha gjyshja. «Ishte një ditë vere, në plazh, dhe mamaja jote kishte blerë akullore. Kur babai yt kaloi me vrap, e shtyu pa dashje, dhe akullorja ra mbi fustanin e saj. Ai u skuq aq shumë, sa i bleu menjëherë dy akullore. Dhe kështu filloi gjithçka.» Ana qeshi. «Prandaj ka një njollë të vogël këtu?» «Pikërisht. Nuk doja ta hiqja.»$s$,
    $s$Ana kaloi gishtin mbi një arnë jeshile, me kuadrate kafe. «Kjo është nga këmisha e gjyshit», tha gjyshja me zë më të ulët. «Ai e mbante kur dilte në kopsht. Mbillte domate, speca e lule. Dhe gjithmonë kishte farat e luleve në xhepin e gjoksit, këtu, në këtë xhep të vogël.» Ana e shikoi me kujdes. Në arnë dukej ende shenja e xhepit, me një qepje të hollë. «Ndonjëherë», tha gjyshja, «kur e prek këtë arnë, më duket sikur ndiej erën e kopshtit të tij.»$s$,
    $s$Ana u ngjit pak më afër arnës dhe e nuhati. Nuk kishte erë kopshti, por kishte erë gjysheje, erë sapuni e erë shtëpie. «Më trego edhe një», tha, ndërsa sytë filluan t'i rëndoheshin pak.$s$,
    $s$Gjyshja zgjodhi vetë këtë herë: një arnë të verdhë, të ndritshme si dielli. «Kjo është nga kapela e verës së xhaxhait tënd, kur ishte i vogël. E humbi në mal, gjatë një shëtitjeje. E kërkuam gjithë ditën, dhe në mbrëmje, kur u kthyem të lodhur, e gjetëm në kokën e dhisë së fqinjit!» Ana qeshi me zë, dhe gjyshja qeshi me të, aq shumë sa iu desh të hiqte syzet.$s$,
    $s$Ana tregoi një arnë të fundit, në qoshe të batanijes, të vogël e gri, pak më të vjetër se të tjerat. «Po kjo?» Gjyshja e preku me shumë butësi. «Kjo», tha, «është nga shalli i nënës sime. Gjyshes së gjyshes tënde. Ma dha kur isha e vogël, sa ti, dhe më tha: Mbaje, që të jem gjithmonë pranë teje. E mbajta gjithë jetën. Dhe kur qepa batanijen tënde, preva një copë të vogël dhe e vura këtu, në qoshe. Që ajo të jetë edhe pranë teje.»$s$,
    $s$Ana e mbajti arnën gri në dorë për një kohë të gjatë. «Pra», tha ngadalë, «në këtë batanije janë të gjithë? Babai, mamaja, gjyshi, xhaxhai, gjyshja e gjyshes?» «Të gjithë», tha gjyshja. «Edhe unë. Shiko, këtu.» Dhe i tregoi një arnë me lule vjollcë. «Kjo është nga përparësja ime e kuzhinës. Ajo me të cilën bëj byrekun që të pëlqen.»$s$,
    $s$«Dhe unë?» pyeti Ana. «Ti je këtu», tha gjyshja, dhe tregoi arnën blu me yje. «Dhe këtu», tregoi një arnë rozë, nga fustani i saj i ditëlindjes së tretë. «Dhe këtu», tregoi një arnë me arinj të vegjël, nga pizhamat e dimrit të kaluar. «Dhe një ditë, kur të rritesh, do të shtosh arna të tjera. Dhe kur të kesh një fëmijë, do t'ia japësh këtë batanije, dhe do t'i tregosh historitë.»$s$,
    $s$Ana u mbështoll mirë me batanijen. E tërhoqi deri në mjekër, dhe ndjeu sikur e përqafonin të gjithë njëkohësisht: babai me këngën e yjeve, mamaja me akulloren, gjyshi me farat e luleve, xhaxhai me kapelën e verdhë, gjyshja e gjyshes me shallin gri, dhe gjyshja me përparësen me lule.$s$,
    $s$«Gjyshe», pëshpëriti Ana me sy pothuajse të mbyllur, «kjo është batanija më e ngrohtë në botë.» «E di pse?» pyeti gjyshja, duke i përkëdhelur flokët. «Sepse është bërë me dashuri. Dhe dashuria nuk ftohet kurrë.»$s$,
    $s$Ana nuk u përgjigj. E kishte zënë gjumi, nën batanijen me arna, me gishtin ende mbi arnën blu me yje. Gjyshja i fiku dritën, i dha një puthje në ballë dhe doli ngadalë nga dhoma. Dhe në errësirë, batanija e mbante Anën të ngrohtë, si gjithë familja bashkë. Natën e mirë, Ana. Natën e mirë, të gjitha arnat.$s$
  ]::text[],
  array['sleep', 'emotions']::text[], 36, 96, 11, 'house',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gbatanijamearna" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gbatanijamearna)"/><rect x="112" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M122 23Q122 26 125 26Q122 26 122 29Q122 26 119 26Q122 26 122 23Z" fill="#F3EBD9"/><circle cx="136" cy="24" r="5" fill="#F3EBD9"/><path d="M129 14V54M112 34H146" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="18" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="21" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><rect x="10" y="10" width="14" height="14" rx="2" fill="#D9644A"/><rect x="25" y="10" width="14" height="14" rx="2" fill="#E7B04B"/><rect x="40" y="10" width="14" height="14" rx="2" fill="#7FB8C6"/><rect x="10" y="25" width="14" height="14" rx="2" fill="#A6CDB4"/><rect x="25" y="25" width="14" height="14" rx="2" fill="#E58C8A"/><rect x="40" y="25" width="14" height="14" rx="2" fill="#C9A0D6"/><rect x="10" y="40" width="14" height="14" rx="2" fill="#E7B04B"/><rect x="25" y="40" width="14" height="14" rx="2" fill="#7FB8C6"/><rect x="40" y="40" width="14" height="14" rx="2" fill="#D9644A"/><path d="M10 25H55M10 40H55M25 10V55M40 10V55" fill="none" stroke="#FFFFFF" stroke-width="1" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
  'published', false, 350, 'editor'
),
(
  $s$rrobat-e-reja-te-perandorit$s$, 'sq', $s$Rrobat e reja të perandorit$s$,
  $s$Sipas Hans Kristian Andersenit: dy mashtrues i shesin perandorit rroba që i shohin vetëm të zgjuarit. Askush s'guxon të thotë të vërtetën, përveç një fëmije.$s$,
  array[
    $s$Shumë vite më parë, jetonte një perandor që i donte rrobat më shumë se çdo gjë tjetër në botë. Nuk i interesonin as ushtarët, as teatri, as shëtitjet në pyll, vetëm nëse kishte rast të tregonte rroba të reja. Kishte një xhaketë për çdo orë të ditës, dhe në vend që njerëzit të thoshin «Perandori është në mbledhje», thoshin «Perandori është në dhomën e veshjes».$s$,
    $s$Një ditë, në qytet erdhën dy të huaj. Thanë se ishin endës, dhe se dinin të endnin pëlhurën më të bukur të botës. Jo vetëm që ngjyrat dhe modelet ishin të mrekullueshme, por pëlhura kishte një veti të çuditshme: ishte e padukshme për këdo që ishte budalla ose që s'e meritonte vendin e tij të punës.$s$,
    $s$«Ç'rroba të shkëlqyera do të ishin!» mendoi perandori. «Po t'i vesha, do ta kuptoja menjëherë cilët nga njerëzit e mi janë budallenj. Dhe do të dalloja të zgjuarit nga të paditurit!» Dhe u dha dy endësve një thes me flori, që të fillonin punën menjëherë.$s$,
    $s$Endësit vunë dy vegje në një dhomë dhe u bënë sikur punonin, ditë e natë. Por në vegje s'kishte asgjë. Kërkuan mëndafshin më të mirë dhe fijet më të çmuara të arit, i futën në çantat e tyre dhe vazhduan të punonin me vegjet bosh deri natën vonë.$s$,
    $s$«Do të doja të dija si po shkon puna», tha perandori pas disa ditësh. Por ndjeu një shqetësim të vogël, kur kujtoi që budallenjtë nuk e shihnin dot pëlhurën. «Më mirë të dërgoj fillimisht dikë tjetër», mendoi. Dhe dërgoi ministrin e tij të vjetër e të ndershëm.$s$,
    $s$Ministri hyri në dhomë, ku endësit punonin me vegjet bosh. Hapi sytë sa mundi. «O Zot», mendoi, «unë s'shoh asgjë!» Por nuk e tha me zë. «Mos vallë jam budalla? Askush s'duhet ta dijë!» Endësit e pyetën: «A s'është e mrekullueshme? Shikoni modelin, shikoni ngjyrat!» «Oh, po, e mrekullueshme», tha ministri. «Do t'i them perandorit që më pëlqen shumë.» Dhe kështu bëri.$s$,
    $s$Pas tij shkoi një nëpunës tjetër, dhe ndodhi e njëjta gjë. Edhe ai s'pa asgjë, dhe edhe ai tha se pëlhura ishte magjepsëse. Gjithë qyteti filloi të fliste për pëlhurën e jashtëzakonshme. Më në fund, shkoi vetë perandori, me gjithë oborrtarët. Ai s'pa asgjë. «Kjo është e tmerrshme!» mendoi. «Mos jam unë budalla? Mos s'e meritoj të jem perandor?» Por tha me zë të lartë: «Oh, është shumë e bukur! Ka miratimin tim të plotë!»$s$,
    $s$U vendos që perandori t'i vishte rrobat e reja në parakalimin e madh të të dielës. Natën para parakalimit, endësit qëndruan zgjuar me gjashtëmbëdhjetë qirinj të ndezur. U bënë sikur hiqnin pëlhurën nga vegjet, e prisnin në ajër me gërshërë të mëdha, e qepnin me gjilpëra pa pe. Në mëngjes thanë: «Rrobat janë gati!»$s$,
    $s$Perandori erdhi. Endësit ngritën krahët në ajër, sikur mbanin diçka. «Ja pantallonat! Ja xhaketa! Ja manteli! Janë të lehta si pëlhura e merimangës. Do të ndiheni sikur s'keni veshur asgjë, por pikërisht kjo është bukuria e tyre.» Perandori i hoqi rrobat e tij, dhe endësit u bënë sikur i vishnin rrobat e reja, një nga një. Perandori u kthye përpara pasqyrës, majtas e djathtas. «Sa mirë më rrinë!» thanë të gjithë oborrtarët.$s$,
    $s$Dhe kështu perandori doli në parakalim, nën një tendë të kuqe, me dy oborrtarë që i mbanin bishtin e mantelit, që s'ekzistonte. Gjithë njerëzit në rrugë dhe në dritare thërrisnin: «Sa të bukura janë rrobat e reja të perandorit! Sa mirë i rri manteli!» Askush nuk donte të tregonte se s'shihte asgjë, sepse askush nuk donte të dukej budalla.$s$,
    $s$Por pastaj, nga mesi i turmës, një fëmijë i vogël që ishte hipur mbi supet e babait, tha me zë të lartë e të qartë: «Por ai s'ka veshur asgjë! Perandori është vetëm me mbathje!»$s$,
    $s$«Dëgjoni zërin e të pafajshmit!» tha babai. Dhe njerëzit filluan të pëshpëritnin njëri-tjetrit: «Ai fëmijë thotë që perandori s'ka veshur asgjë.» Pëshpëritja u bë gjithnjë e më e fortë, deri sa më në fund i gjithë qyteti thirri: «Por ai s'ka veshur asgjë!»$s$,
    $s$Perandori u drodh, sepse e kuptoi që kishin të drejtë. Për një çast, mendoi të vazhdonte parakalimin sikur të mos kishte ndodhur asgjë. Por pastaj pa fëmijën mbi supet e babait, me sytë e tij të sinqertë, dhe ndodhi diçka e papritur: perandori filloi të qeshte. Qeshi me veten, me mbathjet e tij me lule, me oborrtarët që mbanin një mantel të padukshëm. Dhe me të qeshi gjithë qyteti.$s$,
    $s$Endësit kishin ikur prej kohësh, me mëndafshin dhe me arin. Por perandori nuk i ndoqi. Në vend të kësaj, e ftoi fëmijën në pallat dhe i tha: «Ti je i vetmi që më tregove të vërtetën. Çdo herë që të më duhet të di si janë gjërat në të vërtetë, do të të pyes ty.» Dhe që nga ajo ditë, perandori i dëgjonte më shumë ata që i thoshin të vërtetën sesa ata që e lavdëronin.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 48, 120, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="grrobaterejateperando" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E8D5C0"/><stop offset="1" stop-color="#F6EBDD"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#grrobaterejateperando)"/><path d="M-4 96V66.1L8.3 58.1L20.6 66.1V96Z" fill="#C29F80"/><rect x="6.3" y="72.1" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><path d="M21.6 96V57.4L31 49.4L40.5 57.4V96Z" fill="#C29F80"/><rect x="29" y="63.4" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><path d="M120.7 96V63.1L133.4 55.1L146.2 63.1V96Z" fill="#D6BB9F"/><rect x="131.4" y="69.1" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><path d="M147.2 96V67.1L155.2 59.1L163.2 67.1V96Z" fill="#C29F80"/><rect x="153.2" y="73.1" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><circle cx="121.8" cy="20" r="8" fill="#FFF3D6"/><rect x="0" y="96" width="160" height="24" rx="0" fill="#C29F80"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M10 48L12 22L22 34L32 14L42 34L52 22L54 48Z" fill="#E7B04B"/><rect x="10" y="46" width="44" height="8" rx="2" fill="#E7B04B"/><circle cx="32" cy="14" r="3" fill="#D9644A"/><circle cx="12" cy="22" r="2.4" fill="#D9644A"/><circle cx="52" cy="22" r="2.4" fill="#D9644A"/><circle cx="22" cy="50" r="2" fill="#D9644A"/><circle cx="32" cy="50" r="2.2" fill="#4A9C9A"/><circle cx="42" cy="50" r="2" fill="#D9644A"/></g></svg>$s$,
  'published', false, 360, 'editor'
),
(
  $s$kopshti-i-endrrave$s$, 'sq', $s$Kopshti i ëndrrave$s$,
  $s$Kopshtari i natës mbjell çdo mbrëmje fara ëndrrash në jastëkët e fëmijëve. Një natë, Dea e zë duke punuar dhe zgjedh vetë farën e ëndrrës së saj.$s$,
  array[
    $s$Diku, larg, shumë larg, përtej hënës e përtej reve, ka një kopsht që askush s'e ka parë ndonjëherë me sy të hapur. Është kopshti i ëndrrave. Atje rriten lule të çuditshme, që ndriçojnë në errësirë dhe që ndryshojnë ngjyrë sipas ëndrrës që mbajnë brenda. Dhe në atë kopsht punon një kopshtar i vogël, që quhet Kopshtari i Natës.$s$,
    $s$Kopshtari i Natës është i vogël sa një gisht, me një kapelë me majë të mprehtë, me një jelek prej gjethesh e me një shportë të vogël në krah. Çdo mbrëmje, kur fëmijët shkojnë në shtrat, ai mbledh fara nga lulet e kopshtit: fara të kaltra, fara të arta, fara rozë, fara jeshile. Pastaj fluturon me një gjethe të madhe, si me një qilim magjik, deri në dritaret e fëmijëve.$s$,
    $s$Kur fëmija fle, Kopshtari i Natës hyn ngadalë nga dritarja dhe mbjell një farë të vogël në jastëk, pranë veshit. Dhe fara mbin menjëherë, në ëndrrën e fëmijës. Nga një farë e kaltër rritet një ëndërr me det e me peshq. Nga një farë e artë, një ëndërr me diell e me fusha. Nga një farë rozë, një ëndërr me tortë e me ballona. Nga një farë jeshile, një ëndërr me pyje e me kafshë që flasin.$s$,
    $s$Atë mbrëmje, Dea nuk po flinte. Ishte e shtrirë me sytë hapur, duke parë hijet e degëve që lëviznin në tavan. Dhe papritur, pa një dritë të vogël që hyri nga dritarja. Ishte e verdhë e e lëkundshme, si një xixëllonjë. U afrua te jastëku i saj dhe ndaloi. Dea mbylli sytë pothuajse krejt, duke lënë vetëm një çarje të vogël, dhe shikoi.$s$,
    $s$Ishte një njeri i vogël, i vockël, me kapelë me majë dhe me një shportë në krah. Po nxirrte nga shporta një farë të kaltër. «Kush je ti?» pyeti Dea, dhe njeriu i vogël u tremb aq shumë, sa i ra fara dhe u rrokullis në jorgan. «Ti s'flen!» tha me zë të hollë. «Të gjithë fëmijët flenë kur vij unë!»$s$,
    $s$«Unë s'kam gjumë», tha Dea. «Por ti, kush je? Dhe çfarë po bën me jastëkun tim?» Njeriu i vogël mblodhi farën, rregulloi kapelën dhe u përkul. «Jam Kopshtari i Natës», tha. «Mbjell ëndrra. Kjo farë e kaltër do të të jepte një ëndërr për detin. Por meqë je zgjuar, mund të zgjedhësh vetë.»$s$,
    $s$Dea u ngrit ulur në shtrat, me sy të mëdhenj. Kopshtari i Natës hapi shportën dhe i tregoi farat. Ishin të vogla e të ndritshme, si yje të vegjël në fund të shportës. «Kjo e kaltër», tha, «është ëndrra e detit, ku noton me delfinët dhe gjen një kështjellë nën ujë. Kjo e artë, është ëndrra e fushës, ku vrapon me një kalë që di të fluturojë. Kjo rozë, është ëndrra e festës, ku të gjitha lodrat e tua festojnë ditëlindjen tënde.»$s$,
    $s$«Po kjo?» pyeti Dea, dhe tregoi një farë të vogël, të bardhë si qumësht, që shkëlqente më butë se të tjerat. «Kjo», tha Kopshtari, «është një farë e veçantë. Është ëndrra e qetë. Nuk ka aventura, nuk ka festa. Ka vetëm një vend të ngrohtë, ku je e sigurt, ku dikush të do, dhe ku mund të pushosh gjithë natën. Është ëndrra që kanë nevojë fëmijët kur kanë pasur një ditë të gjatë.»$s$,
    $s$Dea u mendua. Atë ditë kishte qenë e gjatë vërtet. Kishte shkuar në kopsht, kishte luajtur në park, ishte rrëzuar nga biçikleta dhe i ishte gërvishtur gjuri, kishte qarë pak, pastaj kishte qeshur shumë me vëllain e saj. Ishte e lodhur, edhe pse s'po flinte. «Atë», tha. «Dua ëndrrën e qetë.»$s$,
    $s$Kopshtari i Natës buzëqeshi, sikur ta kishte ditur që në fillim. «Zgjedhje e mençur», tha. «Shtrihu tani. Dhe mbyll sytë. Farat mbijnë vetëm kur sytë janë të mbyllur.» Dea u shtri, vuri kokën mbi jastëk dhe mbylli sytë. Ndjeu, pranë veshit, diçka të vogël që preku jastëkun, butë si një pëshpëritje.$s$,
    $s$Dhe pastaj, në ëndrrën e saj, mbiu një lule e bardhë, e madhe, me petale të buta si jorgan. Dea u shtri brenda saj, si në një djep. Lulja u mbyll ngadalë rreth saj, e ngrohtë dhe me erë qumështi e mjalti. Dhe nga larg, Dea dëgjoi një këngë të njohur, që i këndonte mamaja kur ishte e vogël. Ndjeu sikur dikush i përkëdhelte flokët. Dhe u ndje e sigurt, shumë e sigurt.$s$,
    $s$Kopshtari i Natës e shikoi për një çast, pastaj mblodhi shportën dhe doli nga dritarja, mbi gjethen e tij fluturuese. Kishte edhe shumë fëmijë të tjerë për të vizituar atë natë, shumë jastëkë për të mbjellë. Por para se të ikte, la mbi komodinën e Deas një farë të vogël të artë. Për nesër.$s$,
    $s$Kur Dea u zgjua në mëngjes, gjeti farën e artë pranë llambës. E mbajti në grusht gjithë ditën, dhe në mbrëmje, para gjumit, e vuri nën jastëk. Dhe atë natë, ëndërroi një kalë që fluturonte mbi fusha të arta. Sonte, para se të mbyllësh sytë, mendo cilën farë do të zgjidhje ti. Dhe pastaj, mbylli sytë. Kopshtari i Natës po vjen.$s$
  ]::text[],
  array['sleep']::text[], 0, 84, 11, 'seed',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkopshtiiendrrave" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkopshtiiendrrave)"/><path d="M133.6 40.7Q133.6 42.7 135.6 42.7Q133.6 42.7 133.6 44.7Q133.6 42.7 131.6 42.7Q133.6 42.7 133.6 40.7Z" fill="#F3EBD9" opacity="0.9"/><circle cx="14.3" cy="38.7" r="1.3" fill="#F3EBD9" opacity="0.7"/><path d="M48.4 29.2Q48.4 31.9 51.1 31.9Q48.4 31.9 48.4 34.6Q48.4 31.9 45.699999999999996 31.9Q48.4 31.9 48.4 29.2Z" fill="#F3EBD9" opacity="0.9"/><circle cx="95.4" cy="16.3" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="144.2" cy="17.7" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="30.5" cy="34.2" r="1.6" fill="#F3EBD9" opacity="0.7"/><circle cx="8.4" cy="18.8" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="38.2" cy="22" r="11" fill="#F3EBD9"/><circle cx="44.2" cy="18" r="10" fill="#1E3446"/><path d="M0 84.3Q40 77.3 80 87.3T160 90.1V120H0Z" fill="#24455A"/><path d="M0 101.3Q40 94.3 80 102.3T160 96.5V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 60V28" fill="none" stroke="#7DA86B" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="24" cy="46" rx="8" ry="3.5" fill="#7DA86B" transform="rotate(-30 24 46)"/><ellipse cx="40" cy="40" rx="8" ry="3.5" fill="#7DA86B" transform="rotate(30 40 40)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#E7B04B"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#E7B04B" transform="rotate(72 32 24)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#E7B04B" transform="rotate(144 32 24)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#E7B04B" transform="rotate(216 32 24)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#E7B04B" transform="rotate(288 32 24)"/><circle cx="32" cy="24" r="5" fill="